// ---- source scanner (skip strings / templates / regex / comments) --------------------
function skipString(s, i, q) { i++; for (; i < s.length; i++) { if (s[i] === "\\") { i++; continue; } if (s[i] === q) return i; } return i; }
function skipRegex(s, i) { i++; let cls = false; for (; i < s.length; i++) { const c = s[i]; if (c === "\\") { i++; continue; } if (c === "[") cls = true; else if (c === "]") cls = false; else if (c === "/" && !cls) return i; } return i; }
function skipTemplate(s, i) {
  i++;
  for (; i < s.length; i++) {
    if (s[i] === "\\") { i++; continue; }
    if (s[i] === "`") return i;
    if (s[i] === "$" && s[i + 1] === "{") {
      i += 2; let depth = 1;
      for (; i < s.length && depth > 0; i++) {
        const c = s[i];
        if (c === "\\") { i++; continue; }
        if (c === "'" || c === '"') { i = skipString(s, i, c); continue; }
        if (c === "`") { i = skipTemplate(s, i); continue; }
        if (c === "{") depth++; else if (c === "}") depth--;
      }
      i--; // for-loop will ++
    }
  }
  return i;
}
function isRegexPos(s, i) {
  let j = i - 1; while (j >= 0 && /\s/.test(s[j])) j--;
  if (j < 0) return true;
  if ("=([,{;:!&|?+-*%<>~^".includes(s[j])) return true;
  return /(?:^|[^\w$])(return|typeof|case|in|of|do|else|void|delete|instanceof|yield|await)$/.test(s.slice(Math.max(0, j - 12), j + 1));
}
// Extract a module-level `const NAME = <expr>;` declaration. extractFn only reaches `function`
// declarations, so a table a function depends on used to have no way into the harness except a
// hand-written stub — and a stub is free to drift from the literal it stands in for. This slices
// the real declaration, matching the same rule the tool-policy deps follow: tests run against the
// real thing or they are not testing it.
function extractConstDecl(name) {
  const m = new RegExp(`\\bconst\\s+${name}\\s*=`).exec(SRC);
  if (!m) throw new Error(`const ${name} not found in main.js`);
  let i = SRC.indexOf("=", m.index) + 1, depth = 0;
  for (; i < SRC.length; i++) {
    const c = SRC[i], d = SRC[i + 1];
    if (c === "/" && d === "/") { i = SRC.indexOf("\n", i); if (i < 0) i = SRC.length; continue; }
    if (c === "/" && d === "*") { i = SRC.indexOf("*/", i + 2) + 1; continue; }
    if (c === "'" || c === '"') { i = skipString(SRC, i, c); continue; }
    if (c === "`") { i = skipTemplate(SRC, i); continue; }
    if (c === "/" && isRegexPos(SRC, i)) { i = skipRegex(SRC, i); continue; }
    if (c === "(" || c === "[" || c === "{") depth++;
    else if (c === ")" || c === "]" || c === "}") depth--;
    else if (c === ";" && depth === 0) return SRC.slice(m.index, i + 1);
  }
  throw new Error(`unterminated declaration extracting ${name}`);
}
function loadConst(name) {
  return new Function(`${extractConstDecl(name)}\n;return ${name};`)();
}
function extractFn(name) {
  const m = new RegExp(`(?:async\\s+)?function\\s+${name}\\s*\\(`).exec(SRC);
  if (!m) throw new Error(`function ${name} not found in main.js`);
  // 先跳过参数表再匹配函数体：默认参数可能含 {}（如 `onRetry = () => {}`），
  // 从参数表里的第一个 { 开始配对会把函数截断在签名中间。
  let p = SRC.indexOf("(", m.index), pd = 0;
  for (; p < SRC.length; p++) {
    const c = SRC[p], d = SRC[p + 1];
    if (c === "/" && d === "/") { p = SRC.indexOf("\n", p); if (p < 0) p = SRC.length; continue; }
    if (c === "/" && d === "*") { p = SRC.indexOf("*/", p + 2) + 1; continue; }
    if (c === "'" || c === '"') { p = skipString(SRC, p, c); continue; }
    if (c === "`") { p = skipTemplate(SRC, p); continue; }
    if (c === "/" && isRegexPos(SRC, p)) { p = skipRegex(SRC, p); continue; }
    if (c === "(") pd++;
    else if (c === ")") { pd--; if (pd === 0) break; }
  }
  let i = SRC.indexOf("{", p), depth = 0;
  for (; i < SRC.length; i++) {
    const c = SRC[i], d = SRC[i + 1];
    if (c === "/" && d === "/") { i = SRC.indexOf("\n", i); if (i < 0) i = SRC.length; continue; }
    if (c === "/" && d === "*") { i = SRC.indexOf("*/", i + 2) + 1; continue; }
    if (c === "'" || c === '"') { i = skipString(SRC, i, c); continue; }
    if (c === "`") { i = skipTemplate(SRC, i); continue; }
    if (c === "/" && isRegexPos(SRC, i)) { i = skipRegex(SRC, i); continue; }
    if (c === "{") depth++;
    else if (c === "}") { depth--; if (depth === 0) return SRC.slice(m.index, i + 1); }
  }
  throw new Error(`unbalanced braces extracting ${name}`);
}
// Strip comments so a "this code must not appear" assertion cannot be satisfied — or defeated —
// by prose. extractFn returns comments verbatim, and the comments explaining a perf fix routinely
// quote the very code the fix removed.
function stripJsComments(source) {
  // 必须**按上下文扫描**，不能用正则。
  //
  // 上一版是两条正则：先去行注释、再去块注释。它认不出**正则字面量**里的 `/`，于是
  // `!/Chrome|Chromium|Edg\//.test(ua)` 这样的真代码里那个 `\//` 被当成行注释开头，
  // 从那儿一路吃到行尾。实测在 main.js 上吃掉 21.7%（821KB）真代码。
  //
  // 后果是双向的，而且反向更危险：assert.match 会静默变红（还能发现），
  // 而 assert.doesNotMatch 在被吃掉的那片区域里**静默变绿** —— 一条本该守着的禁令
  // 等于没写。本仓库 70 处 doesNotMatch(stripJsComments(SRC), ...) 都建立在这上面。
  //
  // 现在逐字符扫，认得字符串 / 模板串 / 正则字面量三种上下文。`/` 前面若是标识符、数字、
  // `)` 或 `]`，那是除号；否则是正则开头 —— 这是 JS 词法里区分这两者的标准启发式。
  const s = String(source);
  let out = "", i = 0, prev = "";
  const regexCanStart = (p) => !/[A-Za-z0-9_$)\]]/.test(p);
  while (i < s.length) {
    const c = s[i], d = s[i + 1];
    if (c === "/" && d === "/") { while (i < s.length && s[i] !== "\n") i++; continue; }
    if (c === "/" && d === "*") { const e = s.indexOf("*/", i + 2); i = e < 0 ? s.length : e + 2; continue; }
    if (c === '"' || c === "'" || c === "`") {
      const q = c; out += c; i++;
      while (i < s.length) {
        const ch = s[i]; out += ch;
        if (ch === "\\") { i++; if (i < s.length) out += s[i]; i++; continue; }
        i++;
        if (ch === q) break;
      }
      prev = q; continue;
    }
    if (c === "/" && regexCanStart(prev)) {
      out += c; i++;
      let inClass = false;
      while (i < s.length) {
        const ch = s[i]; out += ch;
        if (ch === "\\") { i++; if (i < s.length) out += s[i]; i++; continue; }
        i++;
        if (ch === "[") inClass = true;
        else if (ch === "]") inClass = false;
        else if (ch === "/" && !inClass) break;
        else if (ch === "\n") break;
      }
      prev = "/"; continue;
    }
    out += c;
    if (!/\s/.test(c)) prev = c;
    i++;
  }
  return out;
}
// Build the real function with its module-level deps injected as parameters.
let AUTO_LOAD_DEPS = Object.create(null);
function load(name, deps = {}) {
  const resolvedDeps = { ...AUTO_LOAD_DEPS, ...deps };
  const keys = Object.keys(resolvedDeps);
  const fn = new Function(...keys, `${extractFn(name)}\n;return ${name};`);
  return fn(...keys.map((k) => resolvedDeps[k]));
}

function buildRegisteredToolSchemas() {
  // 用户声明的能力也要注入：目录里现在多了「把用户声明推进来」和「把用户关掉的摘出去」
  // 两步。这里给空声明——本函数的用途是拿到**内置**目录，用户声明有自己的测试。
  return new Function(
    "inTauri",
    "_applyCloudToolDescs",
    "_userCapabilities",
    "compileToolSchema",
    "_withoutDisabledTools",
    `${extractFn("_buildAgentToolSchemas")}\n;return _buildAgentToolSchemas;`,
  )(
    true,
    (tools) => tools,
    () => ({ tools: [], commands: [], disabled: [], errors: [] }),
    compileToolSchema,
    (tools) => tools,
  )(true, []);
}
function collectIdentifiers(source, name) {
  const ast = acorn.parse(source, { ecmaVersion: "latest", sourceType: "module" });
  const hits = [];
  const walk = (node, parent = null) => {
    if (!node || typeof node.type !== "string") return;
    if (node.type === "Identifier" && node.name === name) hits.push({ node, parent });
    for (const [key, value] of Object.entries(node)) {
      if (key === "start" || key === "end" || key === "loc") continue;
      if (Array.isArray(value)) for (const child of value) walk(child, node);
      else if (value && typeof value.type === "string") walk(value, node);
    }
  };
  walk(ast);
  return hits;
}

const TO_POSIX = load("_toPosix");
const NORMALIZE_PATH = load("_normalizeFsPath", { _toPosix: TO_POSIX });
const IS_ABSOLUTE_FS_PATH = load("_isAbsoluteFsPath", { _normalizeFsPath: NORMALIZE_PATH });
const PATH_IDENTITY = load("_pathIdentity", {
  _normalizeFsPath: NORMALIZE_PATH,
  _remote: { active: false, platform: "" },
  navigator: { platform: "Linux", userAgent: "" },
});
const COHERENT_PATH = (path) => NORMALIZE_PATH(path);
const NORM_REL = load("_normRel", { _normalizeFsPath: NORMALIZE_PATH, _pathIdentity: PATH_IDENTITY });
const PATH_IS_AT_OR_UNDER = load("_pathIsAtOrUnder", { _pathIdentity: PATH_IDENTITY });

function makeRunEvidenceHelpers(openRoots = []) {
  const allRoots = (preferred = "") => {
    const values = [preferred, ...openRoots]
      .map((value) => NORMALIZE_PATH(String(value || "")).replace(/\/+$/, ""))
      .filter((value) => value && IS_ABSOLUTE_FS_PATH(value));
    return values.filter((value, index) => values.findIndex((known) => PATH_IDENTITY(known) === PATH_IDENTITY(value)) === index);
  };
  const resolveRel = load("_resolveRel", {
    _normalizeFsPath: NORMALIZE_PATH,
    _coherentFilePath: COHERENT_PATH,
    _allRoots: allRoots,
  });
  const evidenceRoot = load("_runEvidenceRoot", {
    _normalizeFsPath: NORMALIZE_PATH,
    _isAbsoluteFsPath: IS_ABSOLUTE_FS_PATH,
    _pathIdentity: PATH_IDENTITY,
    _pathIsAtOrUnder: PATH_IS_AT_OR_UNDER,
    _allRoots: allRoots,
    _resolveRel: resolveRel,
  });
  const evidenceKey = load("_runFileEvidenceKey", {
    _normalizeFsPath: NORMALIZE_PATH,
    _normRel: NORM_REL,
    _pathIdentity: PATH_IDENTITY,
  });
  const evidenceAliases = load("_runFileEvidenceAliases", {
    _runEvidenceRoot: evidenceRoot,
    _normRel: NORM_REL,
    _runFileEvidenceKey: evidenceKey,
  });
  return { allRoots, resolveRel, evidenceRoot, evidenceKey, evidenceAliases };
}

const RUN_EVIDENCE = makeRunEvidenceHelpers();
