test("developer community search is wired through schema, normalization, execution, and truthful fallback", () => {
  assert.match(SRC, /name: "developer_community_search"/);
  assert.match(SRC, /case "developer_community_search": return \{ type: "developer_community_search"/);
  assert.match(SRC, /backend\.invoke\(call\.type, _args\)/);
  assert.match(SRC, /success, empty, rate-limited, failed or timeout/);
  assert.match(SRC, /timeout means that source exceeded this round's hard limit/);
  assert.match(SRC, /empty only means the adapter finished with no usable hits/);
  // 官方语言论坛必须在 sources 描述里点名（模型不知道能传就等于没有）。分隔符用什么无所谓，
  // 原来写死顿号，换成斜杠列举就会假红——守的是"这四个名字都出现"，不是标点。
  for (const forum of ["rust_users", "python_discussions", "swift_forums", "kotlin_discussions"]) {
    assert.match(SRC, new RegExp(forum), `官方论坛来源 ${forum} 必须在 sources 描述里点名`);
  }
  assert.match(SRC, /published_date, created_date, updated_date, last_activity_date and retrieved_at, and these must never stand in for one another/);
  assert.match(SRC, /a missing one stays unknown/);
  assert.match(SRC, /Results keep each source's own relevance or upstream ordering — they are not guaranteed to be sorted by date/);
  assert.match(SRC, /query: \{ type: "string", minLength: 1, description: "The topic or error keyword to search for" \}/);
  assert.match(SRC, /Calling a tool or configuring an endpoint is not success/);
  assert.doesNotMatch(SRC.match(/name: description: "([^"]+)/)?.[1] || "", /真实可运行|代码全有|首选/);

  const directoryDescription = SRC.match(/const _SEARCH_TOOLS_DESCRIPTION = `([^`]+)`;/)?.[1];
  assert.ok(directoryDescription, "search_tools should have a concise runtime description");
  assert.match(directoryDescription, /developer_community_search/);
  assert.match(directoryDescription, /当前支持/);
  assert.match(directoryDescription, /当前时间只表示本轮请求时间/);
  assert.match(directoryDescription, /published_date、updated_at、version、observed_at、rate_date 或 retrieved_at/);
  assert.match(directoryDescription, /最新论文\/SOTA\/前沿研究加载 arxiv_search、openalex_search、crossref_search/);
  assert.match(directoryDescription, /新技术\/新版本\/API 兼容性先查官方文档、包注册表、GitHub\/GitLab\/Gitee\/Codeberg release\/issues 和开发者社区/);
  assert.match(directoryDescription, /医学\/药物\/临床优先加载 pubmed_search、clinical_trials_search、pubchem_search/);
  assert.match(directoryDescription, /游戏价格\/平台加载 steam_search/);
  // live_markets 已删（航班/汇率类工具与代码 IDE 无关），这条对它的目录索引断言随之移除。
  // 同段仍保留对 steam_search 等在册工具的断言，能力目录的契约本身不变。
  assert.match(directoryDescription, /提炼共识、分歧、适用版本\/时间、对当前问题的影响和验证动作/);
  assert.doesNotMatch(directoryDescription, /100%|十倍|全球最大|所有公开仓库|全部免费|秒回|绝不会丢/);
});

test("GitHub repo reader is a real built-in tool, not only an MCP preset", () => {
  const schema = buildRegisteredToolSchemas().find((tool) => tool.function.name === "github_repo");
  assert.ok(schema, "github_repo must be in the live built-in registry");
  assert.deepEqual(schema.function.parameters.required, ["owner", "repo"]);
  assert.ok(schema.function.parameters.properties.action.enum.includes("file"));
  assert.match(schema.function.description, /real contents/);

  // `_mapToolCall(name, args, mcpToolMap = _mcpToolMap)` — the third parameter's DEFAULT
  // dereferences a module-level binding, so omitting it here threw a ReferenceError inside
  // the eval'd copy before any assertion ran. Pass the map explicitly.
  const mapCall = load("_mapToolCall", {
    _normalizeArgKeys: (args) => args,
    _STR_ARG_KEYS: new Set(),
    _KNOWN_TOOLS: new Set(["github_repo"]),
    _canonicalToolName: () => "",
    _mcpToolMap: new Map(),
  });
  assert.deepEqual(mapCall("github_repo", {
    owner: "vercel", repo: "next.js", action: "file", path: "packages/next/package.json",
  }), {
    type: "github_repo", owner: "vercel", repo: "next.js", action: "file",
    path: "packages/next/package.json", branch: undefined, max_results: undefined,
  });

  const invokeArgs = load("_tauriSearchInvokeArgs");
  assert.deepEqual(invokeArgs({ owner: "vercel", repo: "next.js", action: "tree", path: "src", branch: "canary", max_results: 12 }), {
    query: "", owner: "vercel", repo: "next.js", action: "tree", path: "src", branch: "canary", maxResults: 12,
  });
  assert.match(SRC, /call\.type === "github_repo"/);
  assert.match(SRC, /backend\.invoke\(call\.type, _args\)/);
});

