test("active Skills survive L0 prompt stripping and are inherited by child work", () => {
  const activeSkillsBlock = load("_activeSkillsBlock", {
    _activeSkillIds: new Set(["review"]),
    _fileSkills: [],
    _loadSkillsLocal: () => [
      { id: "review", name: "Strict review", prompt: "Run tests before reporting success." },
      { id: "deploy", name: "Deploy", prompt: "Deploy immediately." },
    ],
  });
  const skillText = activeSkillsBlock();
  assert.match(skillText, /Strict review/);
  assert.match(skillText, /Run tests before reporting success/);
  assert.doesNotMatch(skillText, /Deploy immediately/);

  const preserve = load("_l0MessagesWithSkills");
  const messages = preserve([
    { role: "system", content: "private bundled prompt" },
    { role: "user", content: "review this" },
  ], skillText);
  assert.equal(messages[0].role, "system");
  assert.match(messages[0].content, /Strict review/);
  assert.equal(messages[1].content, "review this");
  assert.ok(!messages.some((message) => message.content.includes("private bundled prompt")));
  // 注入的是"目录 + 常驻全文"这个组合块。光有常驻那半，模型永远不知道还有别的技能
  // 存在——那正是"装了技能却没用上"的成因。
  assert.match(SRC, /run\?\.skillsBlock \?\? _skillsSystemBlock\(\)/);
  // 会跑工具的模式拿整个组合块；聊天模式只拿常驻那半——它不执行工具，
  // 目录里那句「用 read_skill 读」在那儿是死路。
  assert.match(SRC, /const skillsBlock = effectiveMode === "chat" \? _activeSkillsBlock\(\) : _skillsSystemBlock\(\)/);
  assert.match(SRC, /function _skillsSystemBlock\(\) \{\s*return _skillCatalogBlock\(\) \+ _activeSkillsBlock\(\);/);
  assert.match(SRC, /skillsBlock: run\.skillsBlock/);
  assert.doesNotMatch(SRC, /_l0MessagesWithSkills\(messages, skillsBlock \|\|/);

  const bounded = load("_activeSkillsBlock", {
    _activeSkillIds: new Set(["one", "two"]),
    _fileSkills: [],
    _loadSkillsLocal: () => [
      { id: "one", name: "One", prompt: "A".repeat(20_000) },
      { id: "two", name: "Two", prompt: "B".repeat(20_000) },
    ],
  })();
  assert.ok(bounded.length < 10_200, `skill block exceeded budget: ${bounded.length}`);
  // 被截断时要告诉模型剩下的怎么拿。以前只说一句"已截断"，模型除了将就没有别的路；
  // 现在有 read_skill 了，指一下比省这十几个字重要。
  assert.match(bounded, /预算/);
  assert.match(bounded, /read_skill/, "截断了就要指出完整内容怎么取");
});

test("dynamic time and bulky file context stay out of the cached system prefix", () => {
  assert.match(SRC, /const adaptiveBlock = _adaptivePromptBlock\(\);[\s\S]{0,320}const fullPrompt = sysPrompt \+ _modelStyleTuning\(config\.model\) \+ userRulesBlock \+ skillsBlock \+ _authContextBlock\(\) \+ languageBlock \+ adaptiveBlock;/);
  assert.doesNotMatch(SRC, /const fullPrompt = [^\n;]*_currentDateBlock\(\)/);
  assert.doesNotMatch(SRC, /const fullPrompt = [^\n;]*_adaptiveMemoryBlock/,
    "per-query adaptive preference memory must never enter the cached system prefix");
  assert.match(SRC, /\(_adaptiveMemory \? _adaptiveMemory \+ "\\n\\n" : ""\) \+/,
    "adaptive preference memory rides the per-turn dynamic preamble instead");
  assert.match(SRC, /const _timeBlock = _currentDateBlock\(\);[\s\S]{0,140}const _dynPreamble =\s*\n\s*\(_timeBlock \? _timeBlock \+ "\\n\\n" : ""\) \+/);
  // The child context still rides OUTSIDE the cached prefix (that is this test's concern),
  // but retrieval is now ranked by the child's own task: an empty query silently disabled
  // repo-map term ranking, BM25 refs (`!query` early-return) and the whole enrichment
  // branch (empty profile never `applies`) for every sub-agent.
  assert.match(SRC, /const _childQuery = \[description, prompt\]\.filter\(Boolean\)\.join\("\\n"\)\.slice\(0, 2000\);/);
  assert.match(SRC, /const _childContext = _currentDateBlock\(\) \+ `\\n\\n--- 项目上下文 ---\\n` \+ \(await _gatherAgentContext\(_childQuery, root\)\)/);
  assert.doesNotMatch(SRC, /_gatherAgentContext\("", root\)/,
    "a sub-agent must not retrieve project context with an empty query");
  assert.doesNotMatch(SRC, /\+ _currentDateBlock\(\) \+ `\\n\\n--- 项目上下文 ---\\n`/);

  const snippet = load("_contextSnippet");
  const large = "HEAD\n" + "A".repeat(6000) + "\nTAIL";
  const out = snippet(large, 1000, "big file");
  assert.match(out, /big file已截断/);
  assert.match(out, /^HEAD/);
  assert.match(out, /TAIL$/);
  assert.ok(out.length <= 1100, `snippet too large: ${out.length}`);
  assert.doesNotMatch(SRC, /content\.slice\(0, 12000\)/);
  assert.match(SRC, /const _AT_TOTAL = 12_000/);
  assert.match(SRC, /const _AT_FILE_MAX = 4_000/);
  assert.match(SRC, /_mentioned\.slice\(0, 8\)/);
  assert.match(SRC, /entries\.filter\(\(en\) => !en\.is_dir\)\.slice\(0, 3\)/);
});

test("换着工具找同一个不存在的东西，也算原地打转", () => {
  // 用户实拍：view_image image.png 读不到 → 接着 find `**/image*.png` 无匹配 →
  // 再换别的工具。两次是**不同的调用**、各失败一次，所以按签名计数的那道闸（同一调用
  // 连失败 3 次）一次都没响，模型就一直换工具找同一个根本不存在的文件，烧掉 205k token。
  const loop = stripJsComments(extractFn("_runAgenticLoop"));
  assert.match(loop, /const spinTarget = \(\(\) => \{/,
    "没有记录这次调用冲着哪个目标去——就没法识别跨工具追同一个东西");
  // 归一化必须去掉目录和通配符，否则 "image.png" 和 "**\/image*.png" 对不上，等于没做。
  assert.match(loop, /replace\(\/\[\*\?\\\[\\\]\]\/g, ""\)/,
    "目标名没去掉通配符，两次调用永远对不上");
  assert.match(loop, /targetFailSigs\[e\.spinTarget\] \|\|= new Set\(\)/,
    "要按「同一目标上失败过的**不同**调用数」计数，不是按次数");
  // 必须钉在**触发条件**那一行：只查字符串存在会被文案分支里的同一句话骗过去
  //（第一次写这条断言就是这么漏的）。
  assert.match(loop, /dupReads >= 2 \|\| maxTargetToolFails >= 2/,
    "触发条件里没有这一项，闸门还是不会响——文案写得再好也永远不会被用到");
  // 文案要说清是「这东西不存在」，泛泛喊「别打转」它会再换第三个工具找同一个文件。
  assert.match(loop, /都没找到「\$\{stuckTarget\}」/);
  assert.match(loop, /根本不存在/);
  assert.match(loop, /停止换工具找它/);
});

test("有专用工具的事就别走终端——撞上时当场说，而不是写在常驻提示词里", () => {
  // 用户原话：「该用什么就用什么，而不是有能用的工具就一直走终端，然后终端命令也
  // 输入不对导致报错」。查过：撞上这件事时整个仓库没有任何一处提醒过模型。
  // 行为断言在 Rust 侧（shell_shadows_tool_advice 的两条测试）；这里只钉住"它真的接在
  // 命令结果上"，以及"提示只加在结果里、没有塞进每轮都发的提示词"。
  const tasks = readFileSync(new URL("../src-tauri/src/tasks.rs", import.meta.url), "utf8");
  assert.match(tasks, /fn shell_shadows_tool_advice/);
  assert.match(tasks, /if let Some\(tip\) = shell_shadows_tool_advice\(&command\)/,
    "写了函数却没接到命令结果上，等于没做");
  for (const tool of ["read_file", "list_dir", "search", "find_files", "edit_file", "web_fetch"]) {
    assert.ok(tasks.includes(tool), `提示里没点名 ${tool}`);
  }
});

test("harness 以「用户」身份塞进去的每一条，都必须戴编排信封", () => {
  // 这是今天被实拍到四次的同一个病根。провider 兼容性逼得这些注入只能用 role:"user"，
  // 于是它们长得就像用户刚说的话，而且**排在用户真正的请求后面**（最后一位是注意力最高的
  // 位置）。模型的反应有据可查：思考里逐条讨论 harness 的规则，最后写下「这一轮没有新的
  // 用户指令」，然后回一段跟提问无关的收尾话。
  //
  // 网关侧量到的同一件事：编排消息存在的那些请求里，"末条用户消息"的字节数恰好等于编排
  // 消息的字节数——模型看到的最后一句"用户发言"，就是 harness 自己。
  //
  // 一条一条盯没用（今天查出来 10 处里有 8 处没戴）。这条断言按结构扫：循环里每一个
  // role:"user" 的注入都要么戴信封，要么在下面这份**有名有姓**的白名单里。
  const loop = extractFn("_runAgenticLoop");
  const ALLOW = [
    // 引导：内容就是用户自己打的字，本来就该以用户身份出现，不戴信封是对的。
    "content });",
  ];
  const naked = [];
  for (const m of loop.matchAll(/\{\s*role:\s*"user",\s*content:\s*([^\n]{0,80})/g)) {
    const tail = m[1].trim();
    if (tail.includes("_ORCH_NOTE")) continue;
    if (ALLOW.some((a) => tail.startsWith(a))) continue;
    naked.push(tail.slice(0, 60));
  }
  assert.deepEqual(naked, [],
    "这些 harness 注入没戴编排信封，模型会把它们当成用户说的话，并据此判断「用户没有新指令」：\n"
    + naked.map((x) => "  · " + x).join("\n"));
});

test("每轮排在最后的那块运行状态，必须把用户这轮的原话带回来", () => {
  // 光戴信封只解决"这不是用户说的"，不解决"那用户说了什么"——同一个坑今天在工具参数
  // 修复那条路上已经踩过一次。最后一位既然被运行状态占着，就必须由它把原话带回来。
  const src = stripJsComments(SRC);
  assert.match(src, /const _selfMemAsk = _lastRealUserText\(messages\)/,
    "最后那块运行状态没有取回用户原话");
  assert.match(src, /用户这一轮真正要的是下面这句/);
  assert.match(src, /别据此判断"用户没有新指令"/,
    "要明说这件事——实拍到的就是模型据此判定用户没说话");
  assert.match(src, /_selfMemMsg = \{ role: "user", content: _ORCH_NOTE \+ _parts\.join/);
});

test("插进去的消息要带着「没做完的事」一起交给模型，并让它判断合并还是另起", () => {
  // 用户实拍的抱怨：插入的消息"不去处理，没任何有用价值"。机制其实是通的——下一轮会取。
  // 缺的是判断依据：只丢一句"用户插了新指令"，模型不知道当前做到哪、还剩什么，于是要么
  // 敷衍一句，要么把已经做完的从头再做一遍。用户原话：「插入消息的话带着没做完的事情，
  // 看看用不用合并一起做，还是做新的」。
  const snap = load("_runProgressSnapshot", {});

  const text = snap({
    _planSteps: [
      { content: "读懂现有登录流程", status: "completed" },
      { content: "改 auth.js 的会话校验", status: "in_progress" },
      { content: "补一个失效 token 的测试", status: "pending" },
      { content: "跑一遍测试", status: "pending" },
    ],
    _executionEvidence: [{ command: "npm test", exitCode: 1 }],
  }, new Set(["src/auth.js"]));
  assert.match(text, /正在做：改 auth\.js 的会话校验/);
  assert.match(text, /还没做完（2 步）/);
  assert.match(text, /已完成 1 步/);
  assert.match(text, /本轮已改过的文件：src\/auth\.js/);
  assert.match(text, /最近跑过：npm test（退出码 1）/, "跑过什么、过没过，是模型判断该不该重做的依据");

  // 什么都没发生时不硬凑一段空话——空快照就不往插话里塞那一节。
  assert.equal(snap({}, new Set()), "");
  assert.equal(snap(null, null), "");

  const src = stripJsComments(SRC);
  assert.match(src, /const _progress = _runProgressSnapshot\(run, _mutatedFiles\)/,
    "插话注入点没带上进度——模型又要凭空判断了");
  assert.match(src, /当前这件事的进度/);
  assert.match(src, /补充或修正当前这件事.*另起一件事|另起一件事[\s\S]{0,80}补充/,
    "没有把「合并还是另起」这个判断交给模型");
  assert.match(src, /别从头再来，也别把已经做完的重做一遍/);
});

test("收尾那一刻插进来的消息不会被丢掉——转成下一轮，而且不会在对话里出现两遍", () => {
  // 循环结束时原来直接把插话队列置空。用户在最后一秒插的那条就此人间蒸发，
  // 界面上看到的就是"插进去的消息不处理"。
  const src = stripJsComments(SRC);
  assert.match(src, /const _strandedSteer = Array\.isArray\(session\._steerQueue\) \? session\._steerQueue\.splice\(0\) : \[\]/,
    "收尾时没有把残留的插话取出来——它会被下一行置空丢掉");
  assert.match(src, /alreadyInTranscript: true/);
  // 重发时不能再画一遍气泡/记忆：_steerRunningAgent 已经落过了。
  assert.match(src, /if \(!opts\.alreadyInTranscript\) addMessage\("user", text, sess, attachments\)/);
  assert.match(src, /if \(!opts\.alreadyInTranscript\) sess\.memory\.push\(\{ role: "user"/);
  assert.match(src, /sendPrompt\(next\.text, next\.attachments \|\| \[\], config, \{ alreadyInTranscript: !!next\.alreadyInTranscript \}\)/);
});

