test("each of the ten model retries gets one sixty-second pre-progress deadline", () => {
  const stalled = load("_isStalledAiError");
  assert.equal(stalled("模型在 60 秒内没有生成有效内容，已停止本轮，请重试。"), true);
  assert.equal(stalled("模型连续 60 秒没有继续生成有效内容，已停止本轮，请重试。"), true);
  assert.equal(stalled("AI request timed out waiting for response headers after 60 seconds"), true);
  assert.equal(stalled("429 rate limit"), false);
  const strip = load("_stripAiRetryPrefix");
  const providerGateway = load("_isProviderGatewayStatusError", { _stripAiRetryPrefix: strip });
  const retryable = load("_isRetryableAiError", { _isProviderGatewayStatusError: providerGateway, _stripAiRetryPrefix: strip, _isRateLimitedAiError: load("_isRateLimitedAiError", { _stripAiRetryPrefix: strip }) });
  assert.equal(retryable("模型在 60 秒内没有生成有效内容"), true);
  assert.match(SRC, /const repairableToolArgs = !!argIssue && !turnErr && !truncated;[\s\S]{0,100}const retryLimit = repairableToolArgs \? 3 : 0/,
    "tool-schema repair keeps its independent three-response bound");
  assert.doesNotMatch(SRC, /_isTransientTurnErr\(turn\.error\)|_waitForAiRecovery\(/,
    "the outer Agent loop must not multiply the bounded request policy");
  assert.match(SRC, /const _AI_MODEL_RETRY_LIMIT = 4;/);
  assert.match(SRC, /const _AI_MODEL_ATTEMPT_TIMEOUT_MS = 60_000;/);
  assert.match(TAURI_AI, /const RESPONSE_HEADERS_TIMEOUT_SECS: u64 = 60;/);
  assert.match(TAURI_AI, /const STANDARD_FIRST_STREAM_PROGRESS_TIMEOUT_SECS: u64 = 60;/);
  assert.match(TAURI_AI, /const STANDARD_EMPTY_STREAM_PROGRESS_TIMEOUT_SECS: u64 = 60;/);
  assert.doesNotMatch(TAURI_AI, /HIGH_RESPONSE_HEADERS_TIMEOUT_SECS|EXTENDED_RESPONSE_HEADERS_TIMEOUT_SECS/,
    "reasoning effort must not change the per-attempt response-header deadline");
  const browserTimeouts = load("_browserAiStreamTimeouts", { _AI_MODEL_ATTEMPT_TIMEOUT_MS: 60_000 });
  assert.deepEqual(browserTimeouts({ thinkingEffort: "medium" }), { firstProgressMs: 60_000, emptyStreamMs: 60_000, stallMs: 60_000 });
  assert.deepEqual(browserTimeouts({ thinkingEffort: "high" }), { firstProgressMs: 60_000, emptyStreamMs: 60_000, stallMs: 90_000 });
  assert.deepEqual(browserTimeouts({ thinkingEffort: "xhigh" }), { firstProgressMs: 60_000, emptyStreamMs: 60_000, stallMs: 120_000 });
  assert.match(SRC, /readWithProgressDeadline/,
    "the browser SSE reader must use the same bounded useful-progress watchdog as desktop");
  assert.match(SRC, /const progressStartedAt = streamStarted;/,
    "response headers and empty control frames must not restart the browser attempt clock");
  assert.match(TAURI_AI, /StreamProgressDeadline::new\(stream_started, timeouts\)/,
    "desktop first-progress timing must start when the physical request starts");
});

test("visible streams paint all received bytes without proportional catch-up", () => {
  const agentTurn = extractFn("_agentModelTurn");
  const plainTurn = extractFn("sendPrompt");
  const writePreview = extractFn("_scheduleWritePreviewFlush");
  const followUp = extractFn("_agentFollowUp");

  assert.match(SRC, /_shown = acc\.length;\s*renderStream\(acc\);/,
    "plain chat must reveal the complete received snapshot");
  assert.match(plainTurn, /let flushTimer = 0;\s*let flushRaf = 0;/,
    "plain Chat must track its timeout and animation-frame handles separately");
  assert.match(plainTurn, /flushTimer = setTimeout\(\(\) => \{\s*flushTimer = 0;[\s\S]{0,100}queueStreamFrame\(\)/,
    "plain Chat must release the throttle timer before it queues a paint");
  assert.match(plainTurn, /document\.hidden[\s\S]{0,100}flushStream\(\)/,
    "a hidden WebKit document must paint synchronously instead of buffering behind a suspended rAF");
  assert.match(plainTurn, /cancelAnimationFrame\(flushRaf\)/,
    "plain Chat settlement must cancel any delayed animation frame");
  assert.match(agentTurn, /_shownLen = acc\.length;/,
    "Agent replies must reveal the complete received snapshot");
  assert.match(agentTurn, /let flushTimer = 0;\s*let flushRaf = 0;/,
    "Agent streaming must track timeout and animation-frame handles separately");
  assert.match(agentTurn, /flushTimer = setTimeout\(\(\) => \{\s*flushTimer = 0;[\s\S]{0,100}queueRenderFrame\(\)/,
    "an elapsed throttle timeout must release its slot before queuing the paint");
  assert.match(agentTurn, /cancelAnimationFrame\(flushRaf\)/,
    "settlement must cancel a delayed animation frame so it cannot repaint stale content");
  assert.match(writePreview, /entry\._shownLen = target\.length;/,
    "live write previews must reveal the complete decoded snapshot");
  assert.doesNotMatch(writePreview, /Math\.ceil\(remaining \/ 3\)|remaining \* 0\./,
    "write previews must not restore proportional typewriter lag");
  assert.match(followUp, /Math\.max\(0, 90 - \(Date\.now\(\) - _ffLast\)\)/,
    "tool follow-up replies render on the throttled streaming cadence (≥90ms, 同主流式路径)");
});

test("retry timeline keeps response-header latency scoped to each physical attempt", () => {
  const createTimeline = load("_createAgentTimeline");
  const startTurn = load("_agentTimelineStartTurn", {
    _IDE_TIMELINE_STEP_KINDS: new Set(["intent", "main", "aux", "subagent", "repair", "learning", "chat"]),
  });
  const startAttempt = load("_agentTimelineStartAttempt");
  const activeAttempt = load("_agentTimelineActiveAttempt", { _agentTimelineStartAttempt: startAttempt });
  const recordMetric = load("_agentTimelineRecordMetric", { _agentTimelineActiveAttempt: activeAttempt });
  const markProgress = load("_agentTimelineMarkProgress", { _agentTimelineActiveAttempt: activeAttempt });

  const timeline = createTimeline("run_timeline", 1_000);
  const turn = startTurn(timeline, { requestId: "req_timeline", kind: "chat", startedAt: 1_100 });

  startAttempt(turn, 1_100);
  recordMetric(timeline, turn, "requestStarted", 0, 1_100);
  recordMetric(timeline, turn, "responseHeaders", 60_000, 61_100);
  recordMetric(timeline, turn, "gatewayRetry", 0, 61_100, { attempt: 1 });

  startAttempt(turn, 62_000);
  recordMetric(timeline, turn, "requestStarted", 0, 62_000);
  recordMetric(timeline, turn, "responseHeaders", 3_180, 65_180);
  markProgress(timeline, turn, "token", 65_200);

  assert.equal(turn.attempts.length, 2);
  assert.equal(turn.attempts[0].responseHeadersAt - turn.attempts[0].requestStartedAt, 60_000);
  assert.equal(turn.attempts[1].responseHeadersAt - turn.attempts[1].requestStartedAt, 3_180,
    "the retry's 3.18s header time must not inherit the first attempt's minute");
  assert.equal(turn.responseHeadersAt, 65_180, "the turn summary points at the successful attempt");
  assert.equal(timeline.firstModelProgressAt - timeline.startedAt, 64_200,
    "task-level first progress still includes the earlier failed attempt");
});

test("send preflight starts independent work without waiting for semantic routing", () => {
  const send = extractFn("sendPrompt");
  const workspaceAt = send.indexOf("const _workspacePreflightPromise");
  const osAt = send.indexOf("const _osDetailPromise");
  const staleAt = send.indexOf("const _staleEvidencePromise");
  const compactAt = send.indexOf("const compactionTask");
  const joinAt = send.indexOf("const [snapshot, staleEvidence] = await Promise.all([");

  for (const [label, at] of [["workspace", workspaceAt], ["OS", osAt], ["stale evidence", staleAt], ["history compaction", compactAt]]) {
    assert.ok(at >= 0 && at < joinAt, `${label} must start before the first required preflight join`);
  }
  assert.doesNotMatch(send, /await\s+_aiIntentPromise|const _turnIntentVerdict = await/,
    "the visible request must not wait for the auxiliary classifier");
  assert.match(send, /const _turnIntentExactPromise = [\s\S]{0,220}_aiIntentInflight\.get\(_turnIntentKey\)/,
    "the run retains the exact physical classifier promise for later boundaries");
  assert.match(send, /intentState: _turnIntentState/,
    "the exact key, context, promise and result state must travel into the agent run");
  assert.doesNotMatch(send, /await\s+_compactHistoryIfHuge\(/,
    "LLM history compaction must never add its old 20-second serial delay to first output");
  assert.match(send, /_agentContextSnapshotForTurn\(text, _curRoot, _turnEngineeringResolved, \{ coldWaitMs: 1200, memoryRoot: _identityRoot \}\)/,
    "a cold workspace gets only a short foreground digest window while warm-up continues");
  assert.match(send, /const \[snapshot, staleEvidence\] = await Promise\.all\(\[/,
    "workspace snapshot and stale-evidence checks should settle together");
});

test("streaming write paths activate only after the complete JSON string arrives", () => {
  const complete = load("_completeJsonString");
  assert.equal(complete('{"path":"src/App', "path"), null,
    "a partial path must never resolve to the wrong file");
  assert.equal(complete('{"path":"src/App.tsx","content":"half', "path"), "src/App.tsx");
  assert.equal(complete('{"path":"src\\\\quoted\\\"name.ts","content":"x"}', "path"), 'src\\quoted"name.ts');
  assert.equal(complete('{"content":"const x = {\\\"path\\\":\\\"wrong.js\\\"}","path":"src/right.js"}', "path"), "src/right.js",
    "path-looking text inside streamed file content must not become the preview target");
  const streamPath = load("_streamWritePath", { _completeJsonString: complete });
  const contentFirst = { args: '{"content":"' + "x".repeat(100_000), _sc: { start: 12, done: false } };
  assert.equal(streamPath(contentFirst), null);
  assert.equal(contentFirst._pathScanLen, undefined,
    "a content-first stream must not repeatedly scan the growing file body");
  contentFirst.args += '","path":"src/right.js"}';
  contentFirst._sc.done = true;
  assert.equal(streamPath(contentFirst), "src/right.js");
  assert.match(SRC, /for \(const it of items\) \{\s*_settleCallLiveWritePreview\(it\.call, it\.rawResult/,
    "the whole tool batch must settle previews, including pre-execution guard exits");
});

test("write_file streams replace once then append every received Monaco delta", () => {
  let value = "disk version";
  let replacements = 0;
  const appended = [];
  const model = {
    getValue: () => value,
    setValue: (next) => { value = next; replacements++; },
    getLineCount: () => value.split("\n").length,
    getLineMaxColumn: () => (value.split("\n").at(-1) || "").length + 1,
  };
  const file = { model, dirty: false };
  const entry = { _target: "const a = 1;" };
  const preview = { entry, path: "/repo/a.js", file, model, shownContent: null, target: "", userChanged: false, committed: false, rolledBack: false };
  entry._editorPreview = preview;
  const previews = new Map([[preview.path, preview]]);
  const positions = [];
  const flush = load("_flushLiveEditorWritePreview", {
    // 诊断埋点在测试里是无操作：它只写文件，不参与流式语义。
    _wpDiag: () => {},
    _perfPhase: () => {},
    _LIVE_EDITOR_PREVIEW_MAX_CHARS: 16000,
    _rollbackLiveEditorWritePreview: () => {},
    _liveEditorWritePreviews: previews,
    openFiles: new Map([[preview.path, file]]),
    activePath: preview.path,
    monacoEditor: {
      getModel: () => model,
      setPosition: (position) => positions.push(position),
      revealLine: () => {},
    },
    _setModelValueProgrammatically: (_model, next) => { value = next; replacements++; return true; },
    _appendModelTextProgrammatically: (_model, text) => { appended.push(text); value += text; return true; },
  });

  assert.equal(flush(entry), true);
  assert.equal(value, "const a = 1;");
  entry._target += "\nconst b = 2;";
  assert.equal(flush(entry), true);
  assert.equal(value, "const a = 1;\nconst b = 2;");
  assert.equal(replacements, 1, "the old file should be replaced only for the first streamed snapshot");
  assert.deepEqual(appended, ["\nconst b = 2;"], "later chunks should append instead of resetting the whole model");
  assert.ok(positions.length >= 2, "the visible editor should follow the streamed tail");
});

test("large streaming writes stay out of Monaco while the bounded tool card keeps rendering", () => {
  const makeFlush = ({ createdTab }) => {
    let value = "disk version";
    let replacements = 0;
    let rollbacks = 0;
    const model = {
      getValue: () => value,
      setValue: (next) => { value = next; replacements++; },
      getLineCount: () => 1,
      getLineMaxColumn: () => value.length + 1,
    };
    const file = { model, dirty: false };
    const entry = { _target: "x".repeat(16001) };
    const preview = {
      entry, path: "/repo/large.ts", file, model, createdTab,
      shownContent: null, target: "", userChanged: false, committed: false, rolledBack: false,
    };
    entry._editorPreview = preview;
    const flush = load("_flushLiveEditorWritePreview", {
      _wpDiag: () => {},
      _perfPhase: () => {},
      _LIVE_EDITOR_PREVIEW_MAX_CHARS: 16000,
      _liveEditorWritePreviews: new Map([[preview.path, preview]]),
      openFiles: new Map([[preview.path, file]]),
      activePath: preview.path,
      monacoEditor: { getModel: () => model, setPosition: () => {}, revealLine: () => {} },
      _setModelValueProgrammatically: (_model, next) => { value = next; replacements++; return true; },
      _appendModelTextProgrammatically: () => { throw new Error("large preview must not append into Monaco"); },
      _rollbackLiveEditorWritePreview: () => { rollbacks++; preview.rolledBack = true; entry._editorPreview = null; },
    });
    return { entry, preview, flush, stats: () => ({ value, replacements, rollbacks }) };
  };

  const temporary = makeFlush({ createdTab: true });
  assert.equal(temporary.flush(temporary.entry), false);
  assert.deepEqual(temporary.stats(), { value: "disk version", replacements: 0, rollbacks: 1 },
    "an agent-opened large preview must be released before Monaco receives the payload");
  assert.equal(temporary.entry._editorPreviewOutcome, "card-only");

  const userOpen = makeFlush({ createdTab: false });
  assert.equal(userOpen.flush(userOpen.entry), false);
  assert.deepEqual(userOpen.stats(), { value: "disk version", replacements: 0, rollbacks: 1 },
    "a user-open buffer is restored until the successful disk commit applies one final snapshot");
  assert.equal(userOpen.preview.editorSyncPaused, true);
  assert.equal(userOpen.entry._editorPreviewOutcome, "card-only");

  const ensure = extractFn("_ensureLiveEditorWritePreview");
  assert.ok(ensure.indexOf("_LIVE_EDITOR_PREVIEW_MAX_CHARS") < ensure.indexOf("backend.readTextFile"),
    "content-first large calls must be rejected before opening/reading a temporary editor model");
});

test("streaming Monaco buffer sync is throttled while the chat card still paints every frame", () => {
  // 真凶回归：流式写入期间对已打开 Monaco model 的同步若逐帧做，每次 getValue 全文
  // 比对 + applyEdits + TS worker 镜像随文件增长变贵，总代价 O(n²) —— 大文件直接无响应。
  const src = extractFn("_scheduleWritePreviewFlush");
  assert.match(src, /_STREAM_EDITOR_SYNC_MS/,
    "编辑器缓冲区同步必须走节流常量，逐帧同步是大文件无响应的 O(n²) 真凶");
  assert.match(SRC, /const _STREAM_EDITOR_SYNC_MS = 500;/,
    "节流间隔必须 ≥500ms");
  assert.match(extractFn("_settleWritePreview"), /_flushLiveEditorWritePreview\(entry, true\)/,
    "流结束定格必须无条件做一次完整同步，节流不能丢最后一段");
  assert.match(extractFn("_flushLiveEditorWritePreview"), /_perfPhase\(`streamWriteEditorSync n=/,
    "同步路径必须打 _perfPhase 相位标记，纳入哨兵取证");

  let now = 1000;
  let raf = null;
  const flushes = [];
  const schedule = load("_scheduleWritePreviewFlush", {
    requestAnimationFrame: (cb) => { raf = cb; return 1; },
    Date: { now: () => now },
    _clipStreamCode: load("_clipStreamCode", { _STREAM_CODE_WIN: 16000 }),
    _STREAM_EDITOR_SYNC_MS: 500,
    _flushLiveEditorWritePreview: () => { flushes.push(now); return true; },
    _scheduleWritePreviewColor: () => {},
  });
  const entry = { streamCard: { querySelector: () => null }, _target: "a" };
  const frame = () => { const cb = raf; raf = null; cb(); };
  schedule(entry); frame();                                    // 首帧：立即同步一次
  now = 1016; entry._target += "b"; schedule(entry); frame();  // 16ms 后：节流跳过
  now = 1032; entry._target += "c"; schedule(entry); frame();  // 仍跳过
  now = 1600; entry._target += "d"; schedule(entry); frame();  // ≥500ms：再同步
  assert.deepEqual(flushes, [1000, 1600],
    "Monaco 同步必须 ≥500ms 一次；首次不等待，中途逐帧调用被合并");
});

test("perf sentinel samples WebKit gaps without permanent rAF and serializes log writes", () => {
  // 哨兵版本自证：取证时必须能一眼确认运行页面装的是哪版取证代码。
  assert.match(SRC, /SENTINEL v3 loaded \$\{new Date\(\)\.toISOString\(\)\}/,
    "哨兵初始化必须向 perf 日志追加版本戳");
  // longtask 是 Chromium 专属，macOS WKWebView 不支持 —— 必须有低频事件循环间隙采样。
  const probeStart = SRC.indexOf("const _rafGapProbe");
  assert.ok(probeStart > 0, "必须存在 rAF 间隙采样探针（longtask 的 WebKit 替代轨）");
  const probe = SRC.slice(probeStart, probeStart + 1800);
  assert.match(probe, /RAFGAP \$\{gap\}ms lastPhase=/, "RAFGAP 行必须带最近一次相位名");
  assert.match(probe, /gap > 500/, "间隙阈值必须 >500ms");
  assert.match(probe, /document\.hidden/, "必须复用 hidden 判据过滤页面隐藏导致的 rAF 暂停误报");
  assert.match(probe, /drift/, "必须复用时钟漂移判据过滤系统睡眠误报");
  assert.match(probe, /setTimeout\(_rafGapProbe, _PERF_GAP_PROBE_MS\)/,
    "探针应低频调度，不能用永久 rAF 让空闲 WebView 保持 60fps");
  assert.doesNotMatch(probe, /requestAnimationFrame\(_rafGapProbe\)/,
    "性能探针本身不能永久唤醒渲染管线");
  const logStart = SRC.indexOf("const _perfLogPending");
  const logBlock = SRC.slice(logStart, logStart + 2200);
  assert.match(logBlock, /if \(_perfLogWriting\) return;/,
    "perf log writes must be single-flight");
  assert.match(logBlock, /_perfLogPending\.splice\(0, _perfLogPending\.length\)\.join\("\\n"\)/,
    "records that arrive during I/O must be coalesced into the next bounded batch");
});

test("cancelled write previews restore existing editors and remove temporary new-file tabs", async () => {
  let existingValue = "partial Agent output";
  const existingModel = { getValue: () => existingValue, setValue: (next) => { existingValue = next; } };
  const existingFile = { model: existingModel, dirty: false };
  const existingEntry = {};
  const existingPreview = {
    entry: existingEntry,
    path: "/repo/a.js",
    file: existingFile,
    model: existingModel,
    originalContent: "original disk content",
    originalDirty: false,
    originalActivePath: "/repo/a.js",
    originalViewState: { lineNumber: 3 },
    createdTab: false,
    userChanged: false,
    committed: false,
    rolledBack: false,
  };
  existingEntry._editorPreview = existingPreview;
  const existingFiles = new Map([[existingPreview.path, existingFile]]);
  const existingPreviews = new Map([[existingPreview.path, existingPreview]]);
  const lsp = [];
  const rollbackExisting = load("_rollbackLiveEditorWritePreview", {
    _liveEditorWritePreviews: existingPreviews,
    openFiles: existingFiles,
    activePath: existingPreview.path,
    _setModelValueProgrammatically: (_model, next) => { existingValue = next; return true; },
    lspManager: { didChange: (path) => lsp.push(path) },
    markDirty: (_path, dirty) => { existingFile.dirty = dirty; },
    monacoEditor: { restoreViewState: () => {} },
    activate: () => {},
    closeFile: async () => true,
  });
  assert.equal(rollbackExisting(existingPreview), true);
  assert.equal(existingValue, "original disk content");
  assert.deepEqual(lsp, ["/repo/a.js"]);
  assert.equal(existingPreviews.size, 0);

  const newModel = { getValue: () => "new partial", setValue: () => {} };
  const newFile = { model: newModel, dirty: false };
  const newEntry = {};
  const newPreview = {
    entry: newEntry,
    path: "/repo/new.js",
    file: newFile,
    model: newModel,
    originalContent: "",
    originalDirty: false,
    originalActivePath: "/repo/a.js",
    createdTab: true,
    userChanged: false,
    committed: false,
    rolledBack: false,
  };
  newEntry._editorPreview = newPreview;
  const newFiles = new Map([[newPreview.path, newFile], ["/repo/a.js", existingFile]]);
  const newPreviews = new Map([[newPreview.path, newPreview]]);
  const closed = [];
  const activated = [];
  const rollbackNew = load("_rollbackLiveEditorWritePreview", {
    _liveEditorWritePreviews: newPreviews,
    openFiles: newFiles,
    activePath: newPreview.path,
    _setModelValueProgrammatically: () => false,
    lspManager: { didChange: () => {} },
    markDirty: () => {},
    monacoEditor: { restoreViewState: () => {} },
    activate: (path) => activated.push(path),
    closeFile: async (path) => { closed.push(path); newFiles.delete(path); return true; },
  });
  assert.equal(rollbackNew(newPreview), true);
  await Promise.resolve();
  assert.deepEqual(closed, ["/repo/new.js"]);
  assert.deepEqual(activated, ["/repo/a.js"]);
});

test("user-owned dirty buffers refuse previews and are never rolled back", () => {
  const dirtyFile = { model: { getValue: () => "user typing" }, dirty: true };
  const install = load("_installLiveEditorWritePreview", {
    _liveEditorWritePreviews: new Map(),
    activePath: "/repo/a.js",
    monacoEditor: { saveViewState: () => null },
    activate: () => {},
  });
  assert.equal(install({}, "/repo/a.js", dirtyFile), null);

  const preview = { path: "/repo/a.js", file: dirtyFile, model: dirtyFile.model, userChanged: true, committed: false, rolledBack: false };
  const previews = new Map([[preview.path, preview]]);
  const rollback = load("_rollbackLiveEditorWritePreview", {
    _liveEditorWritePreviews: previews,
    openFiles: new Map([[preview.path, dirtyFile]]),
  });
  assert.equal(rollback(preview), false);
  assert.equal(dirtyFile.model.getValue(), "user typing");
});

test("atomic write handoff keeps the final streamed Monaco snapshot without a second replacement", () => {
  let value = "final streamed content";
  let sets = 0;
  const model = { getValue: () => value, setValue: (next) => { value = next; sets++; } };
  const file = { model, name: "a.js", dirty: false, diskContent: "old", externalConflict: false };
  const entry = {};
  const preview = { entry, path: "/repo/a.js", file, model, target: value, userChanged: false, committed: false, rolledBack: false };
  entry._editorPreview = preview;
  const previews = new Map([[preview.path, preview]]);
  const take = load("_takeLiveEditorWritePreview", {
    _liveEditorWritePreviews: previews,
    _coherentFilePath: COHERENT_PATH,
  });
  const lsp = [];
  const openFiles = new Map([[preview.path, file]]);
  const apply = load("_applyDiskContentToOpenFile", {
    _coherentFilePath: COHERENT_PATH,
    _openingFiles: new Map(),
    openFiles,
    activePath: "",
    monacoEditor: {},
    _takeLiveEditorWritePreview: take,
    _setModelValueProgrammatically: (_model, next) => {
      if (value === next) return false;
      value = next; sets++; return true;
    },
    lspManager: {
      didChange: (path) => lsp.push(["change", path]),
      didSave: (path) => lsp.push(["save", path]),
    },
    markDirty: (_path, dirty) => { file.dirty = dirty; },
  });

  assert.deepEqual(apply(preview.path, value), { state: "updated" });
  assert.equal(sets, 0, "the committed content is already visible and must not jump through setValue again");
  assert.equal(preview.committed, true);
  assert.equal(file.diskContent, value);
  assert.deepEqual(lsp, [["change", preview.path], ["save", preview.path]],
    "the language server receives one final snapshot and save after streaming settles");
  assert.match(extractFn("_executeToolStepInner"), /liveWritePreview\.existed !== existed[\s\S]{0,120}liveWritePreview\.originalContent !== old/,
    "a disk change during generation must reject the write instead of adopting the newer version as an overwrite base");
});

test("failed terminal commands extract evidence paths and permit one recovery re-read", () => {
  const clean = load("_cleanCommandFailurePath");
  const extract = load("_extractCommandFailureEvidence", {
    _cleanCommandFailurePath: clean,
    _normRel: NORM_REL,
  });
  const mark = load("_markCommandFailureRecovery", {
    _normRel: NORM_REL,
    _markDebugFailure: () => {},
  });
  const consume = load("_consumeFailureReviewRead", { _normRel: NORM_REL });
  const output = [
    "npm error code EJSONPARSE",
    "npm error JSON.parse Invalid package.json: JSONParseError: Expected double-quoted property name",
    "npm error A complete log of this run can be found in: /Users/michael/.npm/_logs/2026-07-13T21_11_54_220Z-debug-0.log",
  ].join("\n");

  const evidence = extract("npm run check && npm test", output, "/repo");
  assert.ok(evidence.files.includes("package.json"));
  assert.ok(evidence.logs.includes("/Users/michael/.npm/_logs/2026-07-13T21_11_54_220Z-debug-0.log"));

  const run = {};
  mark(run, "/repo", { ...evidence, command: "npm run check && npm test" });
  assert.equal(consume(run, "/repo", "package.json"), "上一条命令失败后的复核读取");
  assert.equal(consume(run, "/repo", "package.json"), "", "the failure-review bypass is single-use, not a license to loop");
});

