test("Michael Design 默认栈行为矩阵：无栈才默认，现有栈和用户指定优先", () => {
  const stackRule = SRC.slice(SRC.indexOf("const _MD_STACK_RULE"), SRC.indexOf("const _AGENT_ROLE_BLOCKS"));
  const designPrompt = load("_DESIGN_RESEARCH_PROMPT", {
    _P: (_key, fallback) => fallback,
  });
  const prompt = designPrompt("按需修改网站");
  const matrix = [
    { scenario: "空项目", evidence: /工作区为空/, decision: /React \+ Tailwind CSS \+ shadcn\/ui/ },
    { scenario: "项目没有网站", evidence: /项目没有网站/, decision: /React \+ Tailwind CSS \+ shadcn\/ui/ },
    { scenario: "明确重构且无可沿用栈", evidence: /明确重做且没有可沿用/, decision: /React \+ Tailwind CSS \+ shadcn\/ui/ },
    { scenario: "现有 Vue\/Svelte\/Django 网站", evidence: /已有可运行网站沿用/, decision: /框架、语言、构建工具、组件库和样式方案/ },
    { scenario: "用户指定 Astro\/Vue\/Svelte 等栈", evidence: /用户明确指定/, decision: /服从用户/ },
  ];
  for (const row of matrix) {
    assert.match(stackRule + "\n" + prompt, row.evidence, `${row.scenario}: 缺少触发条件`);
    assert.match(stackRule + "\n" + prompt, row.decision, `${row.scenario}: 缺少技术栈决策`);
  }
  assert.match(stackRule + prompt, /默认栈只适用于这些无栈场景/);
  assert.match(stackRule + prompt, /不得覆盖已有网站/);
  assert.match(prompt, /knowledge_search\(domain="michael-design"\)/,
    "设计子智能体必须调用真实 Michael Design 知识库，不得只读硬编码栈规则");
});

test("web_scaffold 铺的就是真实 Michael Design 基座", () => {
  const RS = readFileSync(join(HERE, "../src-tauri/src/web_scaffold.rs"), "utf8");
  // 空/未知框架必须落到 React——此前落到 Vue 分支，模型照着 React 提示却拿到 Vue 项目
  assert.match(RS, /!matches!\(\s*fw\.as_str\(\),\s*"vue"/,
    "只有明确点名 Vue 系才走 Vue；空值/未知一律 React");
  assert.match(RS, /const MD_TEMPLATES: &\[\(&str, &str\)\] = &\[/, "模板表必须存在");
  assert.match(RS, /include_str!\("\.\.\/templates\/michael-design\//, "模板用 include_str! 编进二进制");
  // 旧的 JS 模板必须真的删掉，否则会和真实基座并存漂移
  for (const dead of ["const MAIN_JSX:", "const APP_JSX:", "const VITE_CONFIG_REACT:"]) {
    assert.ok(!RS.includes(dead), `被取代的旧 React 模板必须删除：${dead}`);
  }
  // 真实模板必须齐全且能编译（已在浏览器里验证过渲染）
  const T = join(HERE, "../src-tauri/templates/michael-design");
  for (const f of ["package.json", "tsconfig.json", "vite.config.ts", "src/index.css",
                   "src/lib/utils.ts", "src/components/ui/button.tsx", "src/components/motion/section-reveal.tsx"]) {
    assert.ok(existsSync(join(T, f)), `缺模板文件：${f}`);
  }
  const pkg = JSON.parse(readFileSync(join(T, "package.json"), "utf8"));
  const deps = { ...pkg.dependencies, ...pkg.devDependencies };
  for (const d of ["react", "typescript", "tailwindcss", "@tailwindcss/vite",
                   "class-variance-authority", "clsx", "tailwind-merge", "lucide-react"]) {
    assert.ok(deps[d], `模板 package.json 缺少 ${d}`);
  }
  assert.ok(!deps.sonner, "sonner 在真实站点零引用，不得进模板");
  assert.ok(!deps.gsap, "gsap 只服务一个滚动叙事区块，不属于基座");
  assert.ok(!deps.postcss && !deps.autoprefixer, "Tailwind v4 CSS-first：不得带 postcss/autoprefixer");
  assert.ok(!existsSync(join(T, "tailwind.config.js")) && !existsSync(join(T, "postcss.config.js")),
    "模板里不得出现 v3 配置文件");
  // 令牌必须是真站点那套（十六进制 zinc + @theme inline），不是通用 shadcn oklch
  const css = readFileSync(join(T, "src/index.css"), "utf8");
  assert.match(css, /@import "tailwindcss";/, "CSS 入口必须是 v4 写法");
  assert.match(css, /@theme inline/, "令牌必须通过 @theme inline 注册");
  assert.match(css, /--radius:\s*0\.75rem/, "圆角标量必须和真实站点一致");
  assert.doesNotMatch(css, /oklch\(/, "真实站点用十六进制 zinc，不是 oklch");
});

test("_runHasOrientationFacts counts only what the run actually observed", () => {
  const oriented = load("_runHasOrientationFacts", {
    _ORIENTING_TOOLS: new Set(["list_dir", "find_files", "read_file", "find_symbol", "semantic_search", "grep_search"]),
  });
  // no bookkeeping → never invent a block
  assert.equal(oriented(null), true);
  assert.equal(oriented({}), false, "a run that has done nothing is not oriented");
  // a real read counts
  assert.equal(oriented({ ctx: { filesRead: new Set(["src/a.ts"]) } }), true);
  assert.equal(oriented({ ctx: { filesRead: new Set() } }), false, "an empty read set is not orientation");
  // a successful orientation tool counts; a failed one does not
  assert.equal(oriented({ _toolLedger: { entries: [{ tool: "list_dir", ok: true }] } }), true);
  assert.equal(oriented({ _toolLedger: { entries: [{ tool: "list_dir", ok: false }] } }), false,
    "a FAILED list_dir observed nothing");
  // acting is not observing — a prior command or write is not orientation
  assert.equal(oriented({ _toolLedger: { entries: [{ tool: "run_cmd", ok: true }, { tool: "write_file", ok: true }] } }), false,
    "running commands and writing files is not looking at the workspace");
});

test("a destructive shell command with zero observed facts executes and reports scope advice", () => {
  const inner = extractFn("_executeToolStepInner");
  assert.match(SRC, /commandRisk === "danger" \|\| _looksLikeShellFileRewrite\(call\.command\)/,
    "the advisory reuses the existing command-risk classification");
  assert.match(SRC, /!run\._emptyRootAtStart && !run\._cmdGroundingDeferred && !_runHasOrientationFacts\(run\)/,
    "the extra scope note is bounded and disappears after real orientation");
  assert.doesNotMatch(inner, /NOT_RUN·先确认作用域|return \{ type: "cmd"[^}]*先确认作用域/,
    "scope advice must never replace terminal execution with a fabricated result");
  assert.match(inner, /const result = await _agentRunInTerminal\(root, call\.command, step, call\.timeoutSecs\)/,
    "the command always reaches the real terminal executor, carrying the model's explicit timeout");
  assert.match(inner, /〔作用域提示·不拦截〕/,
    "the real command result carries a non-blocking scope warning");
  assert.match(inner, /if \(_scopeAdvice\) _content \+= _scopeAdvice;/,
    "the scope warning is appended to exit code, stdout, and stderr after execution");
  assert.match(inner, /_snapshotCmdScope\(root \|\| rootPath\)/,
    "mutating commands retain their pre-command snapshot");
});

test("a mutating command reports which files it actually touched, not just how many", () => {
  assert.match(SRC, /_plan\.slice\(0, 20\)\.map\(\(s\) => `\$\{_normRel\(s\.path, root \|\| rootPath\)\}/,
    "the already-computed before/after diff must be enumerated for the model");
  assert.match(SRC, /本次命令实际改动 \$\{_plan\.length\} 个文件：/);
  assert.doesNotMatch(SRC, /本次命令改动了 \$\{_plan\.length\} 个文件；/,
    "the bare count discarded an observed fact the harness already held");
});

