// ── P1 工具重构聚焦测试 ──

test("P1 _toolFailureKey: git/gh 按 op 分开计数", () => {
  const fingerprint = load("_resultFingerprint");
  const stableValue = load("_stableToolValue");
  const stableSignature = load("_stableToolCallSignature", { _stableToolValue: stableValue, _resultFingerprint: fingerprint });
  const fn = load("_toolFailureKey", { _stableToolCallSignature: stableSignature, _resultFingerprint: fingerprint });
  // git 不同 op 必须有不同失败键
  assert.equal(fn({ type: "git", op: "push" }), "git:push", "git push 失败键必须是 git:push");
  assert.equal(fn({ type: "git", op: "status" }), "git:status", "git status 失败键必须是 git:status");
  assert.equal(fn({ type: "git", op: "commit" }), "git:commit", "git commit 失败键必须是 git:commit");
  // gh 不同 op 也分开
  assert.equal(fn({ type: "gh", op: "pr_create" }), "gh:pr_create", "gh pr_create 失败键必须是 gh:pr_create");
  assert.equal(fn({ type: "gh", op: "pr_view" }), "gh:pr_view", "gh pr_view 失败键必须是 gh:pr_view");
  // 文件类仍保留可读目标；其他工具按完整参数生成不泄露内容的稳定哈希。
  assert.match(fn({ type: "read" }), /^read:[a-z0-9]+:\d+$/, "无目标的读取也必须避免与其他读取连坐");
  const webA = fn({ type: "web_search", query: "alpha" });
  const webB = fn({ type: "web_search", query: "beta" });
  assert.notEqual(webA, webB, "不同搜索目标不能共享失败计数");
  assert.match(webA, /^web_search:[a-z0-9]+:\d+$/, "通用失败键只暴露类型和哈希");
  assert.equal(fn({ type: "read", path: "package.json" }, "/work/a"), "read:/work/a:package.json");
  assert.equal(fn({ type: "find", pattern: "*.ts" }, "/work/a"), "find:/work/a:*.ts");
  assert.notEqual(
    fn({ type: "read", path: "package.json" }, "/work/a"),
    fn({ type: "read", path: "tsconfig.json" }, "/work/a"),
    "不同读取目标不能共享失败计数",
  );
  assert.notEqual(
    fn({ type: "read", path: "package.json" }, "/work/a"),
    fn({ type: "read", path: "package.json" }, "/work/b"),
    "不同工作区的同名文件不能共享失败计数",
  );
  // db 按 op 分开
  assert.equal(fn({ type: "db", op: "query" }), "db:query", "db query 失败键必须是 db:query");
  // 文件变更类按「类型+路径」分开计数：一个文件写失败不得连坐封死其他文件的写入
  assert.equal(fn({ type: "write", path: "packages/a/types.ts" }), "write:packages/a/types.ts");
  assert.equal(fn({ type: "write", path: "packages/b/base.ts" }), "write:packages/b/base.ts");
  assert.notEqual(
    fn({ type: "write", path: "packages/a/types.ts" }),
    fn({ type: "write", path: "packages/b/base.ts" }),
    "不同文件的写入失败键必须不同——否则成批新建文件时一个失败会连坐封死全部写入");
  assert.equal(fn({ type: "edit", path: "src/x.ts" }), "edit:src/x.ts");
  assert.equal(fn({ type: "multiedit", path: "src/x.ts" }), "multiedit:src/x.ts");
  assert.equal(fn({ type: "move", to: "src/y.ts" }), "move:src/y.ts", "move 用目标路径 to 作键");
  assert.equal(fn({ type: "write" }), "write", "无路径时回退到 type");
  // 命令按具体命令分开计数：一条命令失败不得连坐封死其它命令（否则终端整体用不了）
  assert.equal(fn({ type: "cmd", command: "pnpm dev" }), "cmd:pnpm dev");
  assert.notEqual(
    fn({ type: "cmd", command: "pnpm dev" }),
    fn({ type: "cmd", command: "ls" }),
    "不同命令的失败键必须不同——否则一条命令失败会把整个终端封死");
  assert.equal(fn({ type: "cmd", command: "  pnpm   dev  " }), "cmd:pnpm dev", "命令键归一化空白");
  // 无 op 的 git/gh 回退到 type
  assert.equal(fn({ type: "git" }), "git", "git 无 op 时回退到 git");
  // null/undefined 安全
  assert.equal(fn(null), "", "null call 必须返回空字符串");
  assert.equal(fn({}), "", "空 call 必须返回空字符串");
});

test("P1 deferred 搜索工具每次显式调用都保持实时", () => {
  // 这些工具仍须在真实注册表中，但不能因为参数相同而跨轮复用旧结果。
  const deferredTools = [
    "package_search", "github_search", "github_repo", "cve_search",
    "wiki_search", "stackoverflow_search", "hackernews_search",
    "developer_community_search", "pubmed_search",
    "arxiv_search", "crossref_search", "openalex_search", "pubchem_search",
    "clinical_trials_search", "mdn_search",
    "bundlephobia_search", "steam_search",
    "iconify_search",
    "codrops_search", "smashingmag_search",
    "awwwards_search",
  ];
  for (const tool of deferredTools) {
    const pattern = new RegExp(`"${tool}"`);
    assert.match(SRC, pattern, `${tool} 必须保留在真实工具注册表`);
  }
  // 这 18 个已折进上面两个聚合工具，不再单独注册。要守的不是"名字还在"，而是**能力还在**：
  // 旧名字仍能解析成对应的 sources / ecosystem，会话中途重复旧调用不会硬失败。
  // （逐条断言在 test/wiring.test.mjs 的 "retired search capability survives the fold"。）
  const foldedTools = [
    "gitlab_search", "gitee_search", "codeberg_search", "sourcegraph_search",
    "devto_search", "juejin_search", "v2ex_search", "segmentfault_search",
    "github_discussions_search", "github_trending", "infoq_search",
    "dockerhub_search", "maven_search", "packagist_search",
    "rubygems_search", "nuget_search", "homebrew_search", "cdnjs_search",
  ];
  const aliasTable = loadConst("_RETIRED_SEARCH_ALIASES");
  for (const tool of foldedTools) {
    assert.equal(typeof aliasTable[tool], "function", `${tool} 折叠后必须仍能解析，不能变成未知工具`);
    const mapped = aliasTable[tool]({ query: "x" });
    assert.ok(["developer_community_search", "package_search"].includes(mapped.type),
      `${tool} 必须落到聚合工具上，实际是 ${mapped.type}`);
  }
  const wrapperSrc = extractFn("_executeToolStep");
  assert.doesNotMatch(wrapperSrc, /_toolResultCache|_CACHEABLE_TOOL_TYPES|_TOOL_CACHE_TTL|_cached/,
    "deferred 搜索也必须进入真实执行器，不得走通用 TTL 缓存");
});

