  assert.ok(fpCalls >= 4, `三条路径都要调用指纹函数（含定义共 ≥4 处），实际 ${fpCalls} 处`);
  // 跳过忽略目录
  assert.match(SRC, /_AGENT_CONTEXT_SKIP_DIRS\.has\(dn\)/,
    "指纹增强必须跳过忽略目录");
