  assert.equal(isExternal("viewimage"), true, "图片画面同样可能被写入指令");
  const branch = SRC.slice(SRC.indexOf('} else if (call.type === "viewimage") {'), SRC.indexOf('} else if (call.type === "screenshot") {'));
