test("被截断的 emoji 不许把整轮请求打死在后端", () => {
  // 用户实拍的红字：`lone leading surrogate in hex escape at line 1 column 47665`。
  // 这句是 Rust serde_json 说的——JS 字符串容得下半个 UTF-16 代理对，JSON.stringify 也照样
  // 输出 \ud83d，但后端拒收，整轮当场失败。来源是截断：代码里到处 .slice() 工具结果和历史，
  // 一刀切在 emoji 中间就留下孤立代理。列号 47665 说明是社区搜索/网页抓取那种大结果。
  const strip = load("_stripLoneSurrogates", {});
  const sanitize = load("_sanitizeProviderMessages", {
    _withoutLegacyReasoningSummary: load("_withoutLegacyReasoningSummary"),
  });

  assert.equal(strip("ok\ud83dtail"), "ok�tail", "孤立的高位代理要被替掉");
  assert.equal(strip("a\udc00b"), "a�b", "孤立的低位代理同样要被替掉");
  assert.equal(strip("ok😀tail"), "ok😀tail", "完整的代理对必须原样保留——修复不能吃掉正常 emoji");
  assert.equal(strip("普通中文 abc"), "普通中文 abc");
  assert.equal(strip(42), 42, "非字符串原样返回");

  // 三种形状都要覆盖：纯文本 content、多模态分片、以及工具调用的 arguments（JSON 字符串）。
  const out = sanitize([
    { role: "user", content: "问题\ud83d" },
    { role: "user", content: [{ type: "text", text: "分片\ud83d" }, { type: "image_url", image_url: { url: "x" } }] },
    { role: "assistant", content: "", tool_calls: [{ id: "c1", function: { name: "f", arguments: '{"q":"参数\ud83d"}' } }] },
  ]);
  assert.doesNotMatch(out[0].content, /[\uD800-\uDFFF]/, "字符串 content 仍带孤立代理");
  assert.doesNotMatch(out[1].content[0].text, /[\uD800-\uDFFF]/, "多模态分片仍带孤立代理");
  assert.doesNotMatch(out[2].tool_calls[0].function.arguments, /[\uD800-\uDFFF]/,
    "工具调用的 arguments 仍带孤立代理——它同样会被后端解析");
  assert.equal(out[1].content[1].image_url.url, "x", "非文本分片不能被动到");

  // 收口必须在这里，而不是散在几十个 slice 点上：漏一个就复发。
  assert.match(extractFn("_sanitizeProviderMessages"), /_wellFormedContent\(providerMessage\.content\)/,
    "出站消息的 content 没有过代理对修复");

  // 手工兜底分支必须单独测：Node 和新版 WebView 都有原生 isWellFormed/toWellFormed，走原生
  // 就永远碰不到那段循环——它是给老 WKWebView 准备的，不测等于没写。变异验证时发现它是盲区，
  // 所以把原生方法临时摘掉，逼代码走兜底。
  const nativeIs = String.prototype.isWellFormed;
  const nativeTo = String.prototype.toWellFormed;
  try {
    delete String.prototype.isWellFormed;
    delete String.prototype.toWellFormed;
    const fallback = load("_stripLoneSurrogates", {});
    assert.equal(typeof "".isWellFormed, "undefined", "原生方法没摘干净，下面测的还是原生路径");
    assert.equal(fallback("ok\ud83dtail"), "ok\uFFFDtail", "兜底：孤立高位");
    assert.equal(fallback("a\udc00b"), "a\uFFFDb", "兜底：孤立低位");
    assert.equal(fallback("ok😀tail"), "ok😀tail", "兜底：完整代理对必须原样保留");
    assert.equal(fallback("😀😀"), "😀😀", "兜底：连续的完整代理对");
    assert.equal(fallback("\ud83d\ud83d"), "\uFFFD\uFFFD", "兜底：两个连着的孤立高位");
    assert.equal(fallback("纯文本"), "纯文本");
  } finally {
    if (nativeIs) String.prototype.isWellFormed = nativeIs;
    if (nativeTo) String.prototype.toWellFormed = nativeTo;
  }
});

test("撞限流不再直接判死：等一会儿自动重来，但预算极小、退避很长", async () => {
  // 用户的话：「502 和 40 几时候记得要重试，不然用户需要一直发继续」。
  //
  // 限流此前是**刻意**排除在重试之外的，理由写在 _isRateLimitedAiError 上面：它每发一次都带
  // 完整上下文，既加深限流又实打实烧配额，历史上出过 25 秒 18 发的请求风暴。那条保护不能撤。
  //
  // 但"直接判死"同样不对：用户看到红字会自己发「继续」——那就是一次重试，只是来得更快
  // （零退避）、更贵（整轮从头再来）。所以给限流一条独立的路：次数极小、退避很长。
  const waits = Number(/const _AI_MODEL_RATE_LIMIT_WAITS = (\d+);/.exec(SRC)[1]);
  const delay = Number(/const _AI_MODEL_RATE_LIMIT_DELAY_MS = ([\d_]+);/.exec(SRC)[1].replace(/_/g, ""));
  assert.ok(waits >= 1 && waits <= 3, `限流等待次数 ${waits} 超出"极小"的范围——这条路的全部安全性就在于它小`);
  assert.ok(delay >= 10_000, `限流退避 ${delay}ms 太短——太快回去只会加深限流，那正是当年请求风暴的成因`);

  // 普通重试的判据里必须**仍然**把限流排除，否则它会同时吃两份预算，风暴就回来了。
  const retryable = load("_isRetryableAiError", {
    _isRateLimitedAiError: load("_isRateLimitedAiError", { _stripAiRetryPrefix: load("_stripAiRetryPrefix", {}) }),
    _isProviderGatewayStatusError: load("_isProviderGatewayStatusError", { _stripAiRetryPrefix: load("_stripAiRetryPrefix", {}) }),
  });
  assert.equal(retryable("ai request failed (429 too many requests)"), false,
    "限流被并回普通重试集合了——它会同时消耗两份预算，25 秒 18 发的风暴就是这么来的");
  assert.equal(retryable("ai request failed (502 bad gateway)"), true, "502 仍然要走普通重试");

  // 行为验证：第一次限流 → 等待 → 自动重来 → 第二次成功，全程不需要用户发「继续」。
  // 退避按依赖注入压到 10ms：这里验的是"会不会自动重来"这个**行为**，真实退避时长由上面
  // 那两条常量断言守着。不压的话这一条测试会真等 15 秒，把整个套件从 5 秒拖到 20 秒。
  const runWithRetry = load("_runModelRequestWithRetry", { _AI_MODEL_RATE_LIMIT_DELAY_MS: 10 });
  let attempts = 0;
  const seen = [];
  const result = await runWithRetry({
    invoke: async (cb) => {
      attempts += 1;
      if (attempts === 1) throw new Error("ai request failed (429 too many requests)");
      cb({ kind: "text", text: "ok" });
    },
    // 显式 true = 这个事件算真实产出（契约见 _runModelRequestWithRetry 里 accepted 那段）。
    // 不给的话"没报错也没产出"会被判成失败，测的就不是限流那条路了。
    onEvent: () => true,
    onRetry: (info) => seen.push(info),
  });
  assert.equal(attempts, 2, "限流之后没有自动重来——用户又得手动发「继续」");
  assert.equal(result.error, "", "自动重来成功之后不该还报错");
  assert.equal(seen.length, 1, "应当正好通知一次「正在等待重试」");
  assert.equal(seen[0].rateLimited, true, "限流的重试通知要能和普通重试区分，否则界面没法说清在等什么");
});

test("chat 模式中断也能从断点继续，不是让用户把整条消息重发一遍", () => {
  // 用户："有时候会中断也要会重试。"
  // agent 模式早就有断点续传（buildResumeInvoke + _streamResumeMode），chat 模式**一直没接**：
  // 连接在出字过程中断掉就直接报错收场。同一个能力两条路一有一无，没有理由。
  const send = extractFn("sendPrompt");
  const at = send.indexOf("invoke: (cb) => chatFn(cb)");
  assert.ok(at > 0, "找不到 chat 模式那次 _runModelRequestWithRetry 调用");
  const call = send.slice(at, at + 3000);

  assert.match(call, /buildResumeInvoke: async \(\{ resume, resumeLimit \}\) => \{/,
    "chat 模式没接断点续传——中断就报错收场，用户只能整条重发");
  // prefill：把已出的正文作为最后一条 assistant 消息，模型接着写而不是重新开始。
  assert.match(call, /\[\.\.\.requestMessages, \{ role: "assistant", content: partial \}\]/,
    "续传必须以已生成的正文作 prefill——否则就是重放，会把已经出过的字再写一遍");
  assert.match(call, /String\(acc \|\| ""\)\.replace\(\/\\s\+\$\/, ""\)/,
    "prefill 结尾不能留空白，上游会直接 400");
  assert.match(call, /if \(!partial\) return null;/,
    "一个字都没出过时不该走续传——那是普通重试的场景");
  // 保守边界：带工具时"参数能解析"不等于"参数完整"，那种判断留给 agent 路径验证过的那套。
  assert.match(call, /if \(useTools\) return null;/,
    "带工具的流不能用这条简化续传：半截工具参数续下去比整轮重来更危险");
  // 每条流式路径都要在调用点过预算——prefill 会让请求变长，可能正好顶过上限。
  assert.match(call, /backend\.aiChat\(requestConfig, _enforceModelRequestBudget\(resumeMsgs\), cb\)/,
    "续传的请求没过预算");
  // 限流的等待要和普通重试在界面上分得开，否则用户不知道在等什么。
  assert.match(call, /rateLimited\s*\n?\s*\?\s*`线路被限流/,
    "限流的提示要和普通重试区分");
});

test("规则拦下的不能写成「用户已拒绝」——用户根本没点过", async () => {
  const denied = load("_userDeniedToolResult", {});
  // 规则拦：要说清是规则、并指出哪份文件；给模型的建议也不同（别绕，去让用户改规则）
  const byRule = denied({ type: "cmd", command: "npm test" }, { by: "rule", detail: ".mrdayone/settings.json" });
  assert.equal(byRule.blockedBy, "rule");
  assert.equal(byRule.userDenied, false, "标成用户拒绝会让失败记忆把仓库规则记成用户的决定");
  assert.match(byRule.content, /权限规则/);
  assert.match(byRule.content, /\.mrdayone\/settings\.json/, "不说在哪，用户还得自己翻三个作用域");
  assert.doesNotMatch(byRule.content, /用户拒绝了这次调用/);
  // 技能范围外：既不是用户不同意，也不是规则
  const bySkill = denied({ type: "web" }, { by: "skill", detail: "docx" });
  assert.equal(bySkill.blockedBy, "skill");
  assert.match(bySkill.content, /allowed-tools/);
  // 用户真的点了拒绝：原样保留旧文案和旧信号
  const byUser = denied({ type: "write", path: "a.js" }, { by: "user", detail: "" });
  assert.equal(byUser.userDenied, true);
  assert.equal(byUser.failure.code, "user_denied");
  assert.match(byUser.content, /用户拒绝了这次调用/);
  // 没带裁决时按用户拒绝处理——旧调用点的行为不变
  assert.equal(denied({ type: "write" }).userDenied, true);

  // 那道门的返回值必须保持布尔：改成返回对象的话 `{ok:false}` 是真值，
  // 全链路的 `if (!(await ...))` 会当场变成一律放行。
  const gate = stripJsComments(extractFn("_approveToolCall"));
  assert.doesNotMatch(gate, /return \{[^}]*ok:\s*false/, "授权门开始返回对象了——这会把门变成一律放行");
  assert.match(gate, /_noteRefusal\("rule", _permRuleSource\(call\)\)/,
    "只说被规则拦了、不说在哪，用户还是得自己翻三个作用域");
  assert.match(gate, /_noteRefusal\("user", ""\)/);
  assert.match(gate, /_noteRefusal\("skill", skillGate\.names\[0\]/,
    "技能范围外不置位的话，会落到默认的「用户拒绝」分支——而用户没点过");
});

test("往上翻之后要有回程入口——跟随是粘性解除的", () => {
  // 按钮必须挂在 composer 里，不能放 #chat 里：切标签时 chatEl 的子节点会被整个清空
  // （removeChild 循环），放进去第一次切标签就没了。
  const shell = readFileSync(join(HERE, "../src/app/Shell.jsx"), "utf8");
  const at = shell.indexOf('id="chatJump"');
  assert.ok(at > 0, "「回到最新」按钮不见了");
  const before = shell.slice(0, at);
  assert.ok(
    before.lastIndexOf('id="composer"') > before.lastIndexOf('id="chat"'),
    "按钮放进了 #chat，切标签时会被 removeChild 循环清掉",
  );
  // 滚动监听器里同步可见性，且只切属性不造 DOM（这个监听器每次滚动都跑）
  const _lisAt = SRC.indexOf('chatEl.addEventListener("scroll"');
  const listener = SRC.slice(_lisAt, SRC.indexOf("{ passive: true });", _lisAt));
  assert.match(listener, /_syncChatJump\(\)/, "滚动时不同步，按钮永远不会出现");
  assert.doesNotMatch(listener, /createElement|innerHTML/, "滚动路径上不许造 DOM");
  // 点击走 _scrollChatBottom：恢复的历史里 markdown/代码卡/图片首帧之后还会长高，
  // 单次赋值会落在半空——而这颗按钮最需要准的就是这一次。
  const _clkAt = SRC.indexOf('$("chatJump")?.addEventListener');
  const click = SRC.slice(_clkAt, SRC.indexOf('$("modePickerBtn")', _clkAt));
  assert.match(click, /_scrollChatBottom\(\)/);
  assert.doesNotMatch(click, /scrollTop\s*=/, "自己赋 scrollTop 会落在半空");
  // 每一处重新钉底都要收起它
  assert.match(SRC, /function _repinChat\(\)\s*\{\s*_chatPinned = true;[\s\S]{0,60}_syncChatJump/);
  // 两种语言都要有文案，否则界面上显示的是 key
  const i18n = readFileSync(join(HERE, "../src/i18n.js"), "utf8");
  assert.equal((i18n.match(/"assistant\.jumpToLatest"/g) || []).length, 2, "少了中文或英文词条");
});

test("跑到一半切模式，要说清从哪一刻起生效", () => {
  const at = SRC.indexOf("已切换到 ${mode.label} 模式");
  assert.ok(at > 0);
  const block = stripJsComments(SRC.slice(at - 300, at + 200));
  // run 在创建时就把 mode 定死了（mode: mode || _currentAiMode），跑到一半切对这一轮
  // 完全没有影响。只说"已切换"，用户会盯着屏幕等它按新模式干活，然后怀疑软件坏了。
  assert.match(block, /_isStreaming\(\)/, "没有区分「正在跑」和「空闲」两种情况");
  assert.match(block, /当前这一轮仍按原模式跑完/);
});

test("一键全撤：不许覆盖你事后自己改过的文件", async () => {
  const disk = new Map([
    ["/r/a.js", "AGENT 写的"],          // 和 current 一致 → 可以撤
    ["/r/b.js", "我后来自己改的"],       // 和 current 不一致 → 必须跳过
    ["/r/c.js", "无所谓"],              // 没有 current（旧数据）→ 不做检测，照撤
  ]);
  const wrote = [];
  const deleted = [];
  const revert = load("_revertRunChanges", {
    _runRevertPlan: load("_runRevertPlan", {}),
    backend: {
      readTextFile: async (p) => { if (!disk.has(p)) throw new Error("ENOENT"); return disk.get(p); },
      writeTextFile: async (p, c) => { wrote.push([p, c]); },
      deletePath: async (p) => { deleted.push(p); },
    },
  });
  const cp = new Map([
    ["/r/a.js", { existed: true, content: "原文 A", current: "AGENT 写的" }],
    ["/r/b.js", { existed: true, content: "原文 B", current: "AGENT 写的 B" }],
    ["/r/c.js", { existed: true, content: "原文 C" }],
    ["/r/new.js", { existed: false, content: "", current: "新建的" }],
  ]);
  const out = await revert(cp);
  assert.deepEqual(out.skipped, ["/r/b.js"], "事后被用户改过的文件被覆盖了——那是毁掉他的编辑");
  assert.deepEqual(wrote.map(([p]) => p).sort(), ["/r/a.js", "/r/c.js"]);
  assert.deepEqual(wrote.find(([p]) => p === "/r/a.js")[1], "原文 A", "写回的必须是本轮开始前的内容");
  assert.deepEqual(deleted, ["/r/new.js"], "本轮新建的文件应当删除，而不是写空");
  assert.equal(out.reverted, 3);

  // 撤销**逻辑**（写回本轮前内容、删新建文件、先确认后动手）仍然要正确——2026-08-18
  // 只删了轮末默认挂那条 UI，函数和 checkpoint 都留着，需要时可另开入口。
  const agentFooter = SRC.slice(SRC.indexOf("elapsedMs: Date.now() - run._recStart"), 
                               SRC.indexOf("elapsedMs: Date.now() - run._recStart") + 500);
  assert.doesNotMatch(agentFooter, /_appendRunRevertBar\(body, run\)/,
    "又把撤销条挂回轮末了 —— 用户点名不要这条");
  const bar = stripJsComments(extractFn("_appendRunRevertBar"));
  assert.match(bar, /_toolApprovalDialog/, "写回是破坏性的，必须先确认");
  assert.match(bar, /if \(ok !== "once"\) return;/,
    "只弹框不看结果，等于没问——用户点了取消照样撤");
  assert.ok(
    bar.indexOf('if (ok !== "once") return;') < bar.indexOf("_revertRunChanges"),
    "确认必须发生在动手之前",
  );
  assert.match(bar, /你自己动过的文件会跳过/, "确认框里要说清哪些不会被碰");
  // 恢复出来的那份没有监听器、也没有 checkpoint，不能跨重启假装还能点
  assert.match(SRC, /\.run-revert-btn, \.agent-files-bar/, "快照清理里去掉了它，恢复后会留一个死按钮");
});

test("每个会弹审批框的工具都得有自己的文案，不能只给一句「执行该操作？」", async () => {
  const { approvalTypes } = await import("../src/agent/tool-policy.js");
  const label = load("_approvalLabel", { _escHtml: String, _dbCallIsDestructive: () => false });
  const generic = label({ type: "__不存在的类型__" }).title;
  const bland = [];
  for (const t of [...approvalTypes()].sort()) {
    const r = label({
      type: t, path: "src/a.js", command: "npm run x", url: "https://x/a", name: "n",
      prompt: "p", op: "pr_create", method: "POST", driver: "postgres", query: "select 1",
      action: "press", ref: 1, dest: "d", to: "t", branch: "b", engine: "godot", text: "t",
    });
    if (!r || !r.title || r.title === generic) bland.push(t);
  }
  // 一个没有信息的框，只会让人闭着眼睛点同意——那时候这道门就只剩摩擦、不剩保护。
  assert.deepEqual(bland, [], "这些工具会弹框，但框上只有一句没信息的默认文案：" + bland.join(", "));
  // 铺一整棵项目树的那两个，必须在框里说清会往工作区写东西——它是这批里代价最大的一个。
  for (const t of ["game_scaffold", "web_scaffold"]) {
    const r = label({ type: t, name: "x", engine: "godot", framework: "react" });
    assert.ok(String(r.detail || "").includes("工作区"),
      `${t} 的确认框没说清会往哪儿写——它会创建一整套目录和文件`);
  }
});

test("审批框要给真实 diff，不能只说「修改文件？src/auth.js」", async () => {
  const { diffStat } = await import("../src/agent/diff-view.js");
  const disk = new Map([["/r/a.js", "line1\nline2\nline3\n"]]);
  const preview = load("_approvalDiffPreview", {
    _diffStat: diffStat,
    backend: { readTextFile: async (p) => { if (!disk.has(p)) throw new Error("ENOENT"); return disk.get(p); } },
  });

  // edit：把真实前后算出来，给出变化的那几行
  const e = await preview({ type: "edit", path: "/r/a.js", oldString: "line2", newString: "改过的第二行" });
  assert.match(e, /\+1 −1/);
  assert.match(e, /- line2/);
  assert.match(e, /\+ 改过的第二行/);
  assert.doesNotMatch(e, /line1/, "只给变化的行，不是整份文件——框是用来一眼看清的");

  // write 到新文件：说清是新建、多少行
  const w = await preview({ type: "write", path: "/r/new.js", content: "a\nb\n" });
  assert.match(w, /新建文件/);

  // multiedit：逐条应用
  const m = await preview({ type: "multiedit", path: "/r/a.js",
    edits: [{ old_string: "line1", new_string: "X" }, { old_string: "line3", new_string: "Y" }] });
  assert.match(m, /\+ X/);
  assert.match(m, /\+ Y/);
  assert.equal(
    await preview({ type: "multiedit", path: "/r/a.js",
      edits: [{ old_string: "line1", new_string: "X" }, { old_string: "不存在的一段", new_string: "Y" }] }),
    "",
    "多步编辑里有一步对不上就整份放弃——顺序依赖，中间落空后面全错位",
  );

  // 对不上就**不猜**：old_string 不在文件里，宁可没有预览也不要编一个假 diff
  assert.equal(await preview({ type: "edit", path: "/r/a.js", oldString: "根本没有这段", newString: "x" }), "");
  // 内容没变要如实说，别显示一个空 diff 让人以为看漏了
  assert.match(await preview({ type: "write", path: "/r/a.js", content: disk.get("/r/a.js") }), /没有变化/);
  // 非文件类调用不读盘
  assert.equal(await preview({ type: "cmd", command: "ls" }), "");

  // 预览必须真的接进那道门
  const gate = stripJsComments(extractFn("_approveToolCall"));
  assert.match(gate, /_approvalDiffPreview\(call\)/, "算了预览却没往框里放");
  assert.equal((gate.match(/\$\{label\.detail\}\$\{_diffPreview\}/g) || []).length, 2,
    "普通分支和「规则要求确认」分支要各拼一次，只改一个的话另一条路上预览会静静消失");
  assert.match(gate, /catch \{ _diffPreview = ""; \}/, "读盘失败必须降级成没有预览，不能让整道门挂掉");
});

test("改写用户标识符必须是用户主动打开的，不能默认替他做主", () => {
  // _fixKeywordTypos 的判据是「和某个关键字/模块 API 的 Levenshtein 距离恰好为 1」，
  // 作用对象是任何长度≥3、全字母、非驼峰、不含下划线的小写词。它分不出「拼错的关键字」
  // 和「我就是要叫这个名字的短变量」——Python 里叫 elf 的变量会被改成 elif、wit 改成 with。
  //
  // 而它改的是**用户已经写下的源码**，无提示、和普通输入一起进 undo 栈，事后极难发现
  // 是谁干的。所以默认必须是关，且必须在设置里能看见、能开。
  assert.match(SRC, /autoFixTypos:\s*false\s*,/,
    "自动改写标识符必须默认关闭——它会把用户自己起的短变量名改掉");
  assert.match(SRC, /effectivePrefs\(\)\.autoFixTypos \? _fixKeywordTypos\(/,
    "_fixKeywordTypos 必须被 autoFixTypos 开关挡着，而不是无条件执行");
  assert.match(SRC, /\{ key: "autoFixTypos", labelKey: "feature\.settings\.autoFixTypos\.label"/,
    "这个开关必须出现在设置里——藏起来的默认值等于没得选");
});

test("脱敏不许改坏普通源码——模型读到的必须还是用户的代码", () => {
  // 按名字打码那条规则匹配的是**任何以 key/token/secret 结尾的标识符**，于是普通源码
  // 被大面积改坏（修复前 ide/src 下 26% 的文件），而这份被改坏的文本正是喂给模型的那一份
  // （当前打开文件、read_file 正文、所有工具结果三条通道都过 _redactSecrets）。
  // 模型读到的不是用户的代码，却要基于它改代码——这是"智能体写出来的东西用不了"的
  // 直接机器原因之一。
  const src = SRC.slice(SRC.indexOf("function _redactSecrets(text, opts)"));
  const body = src.slice(0, src.indexOf("\nfunction "));
  const redact = new Function("text", "opts", body.slice(body.indexOf("{") + 1, body.lastIndexOf("}")) + "\nreturn t;");

  for (const code of [
    "const key = styleKey(cell.s);",
    "const token = parser.nextToken();",
    "cacheKey: computeHash(input)",
    "const apiKey = process.env.API_KEY;",
    "password: currentPassword",
    "let token = ++preloadToken;",
  ]) {
    assert.equal(redact(code), code, `普通源码被脱敏改坏了：${code}`);
  }

  // 反向：真凭据仍然必须被打掉，否则这条"修复"就是把密钥泄漏当成了代码兼容。
  for (const secret of [
    'API_KEY=sk_live_abc123def456',
    'password: "hunter2"',
    "DB_PASSWORD=p4ssw0rd-x9",
  ]) {
    assert.notEqual(redact(secret), secret, `真凭据没有被打码：${secret}`);
  }
});

test("自动改重复标点不许碰别的语言的合法语法", () => {
  // _fixDoublePunctuation 扫的是**整个文件每一行**，既不看语言也不看改动范围，
  // 唯一的闸是「4000 行以上跳过」。`::` `..` `;;` 三条改写在 Rust/C++/Lua/PHP 里是纯破坏：
  // std::collections → std:collections、0..10 → 0.10、for(;;) → for(;)、Lua 的 a..b → a.b。
  // 改完 1.2 秒防抖触发、随后自动保存落盘，全程零提示零开关。
  const tbl = SRC.slice(SRC.indexOf("const _DOUBLE_SYMBOLS = ["), SRC.indexOf("const _BRACKET_PAIRS"));
  for (const [pat, why] of [
    [/\[\/::\(\?!:\)\/g, null\]/, ":: 必须保持 null（Rust/C++/PHP 的路径分隔符）"],
    [/\[\/\\\.\\\.\(\?!\\\.\)\/g, null\]/, ".. 必须保持 null（Rust 区间 / Lua 连接）"],
    [/\[\/;;\/g, null\]/, ";; 必须保持 null（C 的 for(;;)）"],
  ]) {
    assert.match(tbl, pat, why);
  }
});

test("会删东西的 find 不许被判成只读命令，批量删除必须弹确认", () => {
  // 只读判定在审批链里排在 mustAsk **前面**并直接 return true，所以一旦某条命令被判成
  // 只读，它连「改动前审批」都绕得过去——用户自己打开的闸对它无效。而 find 的动作谓词
  // 就长在参数里（-delete / -exec / -ok / -fprint），白名单原来那句「参数不含 ; & | < > 反引号
  // 就算安全」对它根本不成立。再加上 shell 删除不进 checkpoint，「全部撤销」也救不回来。
  const roSrc = SRC.slice(SRC.indexOf("function _looksLikeReadOnlyCommand"));
  const roBody = roSrc.slice(0, roSrc.indexOf("\nfunction "));
  const isReadOnly = new Function("command", roBody.slice(roBody.indexOf("{") + 1, roBody.lastIndexOf("}")).replace(/_looksLikeReadOnlyCommand/g, "arguments.callee") + "");
  // 直接用源码里的谓词判据做断言，避免把整个递归函数搬进沙箱。
  assert.match(roSrc, /const findIsDestructive = \(segment\) =>/,
    "find 的破坏性谓词判断没了——-delete / -exec 会重新被当成只读命令");
  assert.match(roSrc, /-\(\?:delete\|exec\|execdir\|ok\|okdir\|fls\|fprint\|fprintf\)/,
    "破坏性谓词名单不完整");
  assert.match(roSrc, /!findIsDestructive\(segment\) &&/,
    "谓词判断没有真正接到 segmentOk 上——写了等于没写");
  void isReadOnly;

  // auto 模式下唯一会弹确认框的是 _DANGEROUS_CMD_RE，批量不可逆删除必须在里面。
  const m = /const _DANGEROUS_CMD_RE = (\/.*\/i);/.exec(SRC);
  assert.ok(m, "找不到 _DANGEROUS_CMD_RE");
  const RE = eval(m[1]);
  for (const cmd of [
    "find . -name '*.js' -delete",
    "find . -type f -exec rm -rf {} +",
    "git clean -xfd",
    "git clean -f -d",
    "rm -rf .",
    "rm -rf ~/Documents",
  ]) {
    assert.ok(RE.test(cmd), `批量不可逆删除没有被标成危险，auto 模式下会静默执行：${cmd}`);
  }
  // 反向：日常操作不能被误报，否则确认框常亮、然后就没人看了。
  for (const cmd of ["find . -name '*.ts'", "rm -rf node_modules", "git clean -n", "git status", "ls -la"]) {
    assert.ok(!RE.test(cmd), `日常操作被误报成危险，确认框会变成噪声：${cmd}`);
  }
});

test("edit_file 的空白容错不许把 Python 代码块挪进/挪出一层缩进", () => {
  // _recoverEditMatch 有两条容错路径，安全等级不同：
  //   lineWise   —— 归一化后逐行比对；曾经带一个 `(s) => s.trim()`，把**行首缩进**也剥掉
  //   indentNorm —— 校验「每行缩进差值一致」，一致才返回公共前缀让调用方补回去
  // 调用方是 `if (rec.indent) _editReplacement = _reindentReplacement(...)`，
  // 所以不返回 indent 就等于按模型自己的缩进写入。lineWise 排在 indentNorm 前面先 return，
  // 于是那套防护被整个绕过：模型缩进错一级也"匹配成功"，写进去的代码被静默挪进/挪出
  // 一层 if——Python/YAML 语法仍然合法，语义变了，没有任何报错。
  const src = SRC.slice(SRC.indexOf("function _recoverEditMatch(text, needle)"));
  const body = src.slice(0, src.indexOf("\n/// 给 new_string"));
  // 断言钉在**实现**上，不能钉在"源码里不许出现 s.trim()"——上面那段注释里就引用了
  // 这个写法，doesNotMatch 会被自己的注释喂到而误红。改成正面断言归一化数组只剩一项。
  const normArr = /for \(const norm of \[([\s\S]*?)\]\) \{/.exec(body);
  assert.ok(normArr, "找不到 lineWise 的归一化数组");
  assert.equal(normArr[1].split("=>").length - 1, 1,
    "lineWise 的归一化只能有「去行尾空白」一项；带上剥行首缩进的那项会绕过 indentNorm 的安全校验");
  assert.match(normArr[1], /\[ \\t\]\+\$/,
    "保留下来的那一项必须是去**行尾**空白");

  // 先切再替换：replace 会改变长度，拿原串的下标去 slice 会切歪，得到一段语法不全的
  // 函数体，new Function 直接抛 SyntaxError。
  const fn = new Function("text", "needle",
    body.slice(body.indexOf("{") + 1, body.lastIndexOf("}")).replace(/_stripLineNoPrefix\(needle\)/, "null"));
  // 文件里这段在 if 之内（缩进 8），模型给的 old_string 少一级（缩进 4）。
  const file = ["def run(cfg):", "    if cfg.enabled:", "        total = 0", "        total += 1", "    return total"].join("\n");
  const needle = ["    total = 0", "    total += 1"].join("\n");
  const r = fn(file, needle);
  if (r) {
    assert.equal(r.indent, "    ",
      "缩进容错命中却没返回要补回的公共前缀——调用方会按模型的缩进写入，把代码挪出 if");
  }
});
